select public.upsert_bank_question($json${"id":"evan2-easy-001","type":"choice","level":"easy","testament":"nt","book":"MAT","chapter":7,"verse_start":24,"verse_end":24,"texts":{"pt":{"prompt":"Na parábola de Jesus, onde construiu o homem prudente a sua casa?","bible_ref":"Mateus 7:24","verse_text":"Portanto todo o que ouve estas minhas palavras e as pratica, eu o compararei ao homem prudente, que construiu sua casa sobre a rocha."},"fr":{"prompt":"Dans la parabole de Jésus, sur quoi l’homme prudent a-t-il bâti sa maison ?","bible_ref":"Matthieu 7:24","verse_text":"C’est pourquoi, quiconque entend ces paroles que je dis et les met en pratique, sera semblable à un homme prudent qui a bâti sa maison sur le roc."},"en":{"prompt":"In Jesus’ parable, where did the wise man build his house?","bible_ref":"Matthew 7:24","verse_text":"Therefore whosoever heareth these sayings of mine, and doeth them, I will liken him unto a wise man, which built his house upon a rock:"},"es":{"prompt":"En la parábola de Jesús, ¿dónde edificó su casa el hombre prudente?","bible_ref":"Mateo 7:24","verse_text":"Cualquiera, pues, que me oye estas palabras, y las hace, le compararé á un hombre prudente, que edificó su casa sobre la peña;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Sobre a rocha"},"fr":{"text":"Sur le roc"},"en":{"text":"Upon a rock"},"es":{"text":"Sobre la peña"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Sobre a areia"},"fr":{"text":"Sur le sable"},"en":{"text":"Upon the sand"},"es":{"text":"Sobre la arena"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Junto ao rio"},"fr":{"text":"Près du fleuve"},"en":{"text":"By the river"},"es":{"text":"Junto al río"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"No alto de uma árvore"},"fr":{"text":"En haut d’un arbre"},"en":{"text":"Up in a tree"},"es":{"text":"En lo alto de un árbol"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-easy-002","type":"choice","level":"easy","testament":"nt","book":"MAT","chapter":2,"verse_start":11,"verse_end":11,"texts":{"pt":{"prompt":"Que presentes ofereceram os magos ao menino Jesus?","bible_ref":"Mateus 2:11","verse_text":"E entrando na casa, acharam o menino com sua mãe Maria, e prostrando-se o adoraram. E abrindo seus tesouros, ofereceram-lhe presentes: ouro, incenso, e mirra."},"fr":{"prompt":"Quels présents les mages offrirent-ils au petit enfant Jésus ?","bible_ref":"Matthieu 2:11","verse_text":"Ils entrèrent dans la maison, virent le petit enfant avec Marie, sa mère, se prosternèrent et l’adorèrent; ils ouvrirent ensuite leurs trésors, et lui offrirent en présent de l’or, de l’encens et de la myrrhe."},"en":{"prompt":"What gifts did the wise men present to the young child Jesus?","bible_ref":"Matthew 2:11","verse_text":"And when they were come into the house, they saw the young child with Mary his mother, and fell down, and worshipped him: and when they had opened their treasures, they presented unto him gifts; gold, and frankincense, and myrrh."},"es":{"prompt":"¿Qué dones ofrecieron los magos al niño Jesús?","bible_ref":"Mateo 2:11","verse_text":"Y entrando en la casa, vieron al niño con su madre María, y postrándose, le adoraron; y abriendo sus tesoros, le ofrecieron dones, oro é incienso y mirra."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Ouro, incenso e mirra"},"fr":{"text":"De l’or, de l’encens et de la myrrhe"},"en":{"text":"Gold, frankincense and myrrh"},"es":{"text":"Oro, incienso y mirra"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Pão, peixe e vinho"},"fr":{"text":"Du pain, du poisson et du vin"},"en":{"text":"Bread, fish and wine"},"es":{"text":"Pan, peces y vino"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Prata, azeite e mel"},"fr":{"text":"De l’argent, de l’huile et du miel"},"en":{"text":"Silver, oil and honey"},"es":{"text":"Plata, aceite y miel"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Ovelhas, cabras e pombas"},"fr":{"text":"Des brebis, des chèvres et des colombes"},"en":{"text":"Sheep, goats and doves"},"es":{"text":"Ovejas, cabras y palomas"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-easy-003","type":"choice","level":"easy","testament":"nt","book":"MAT","chapter":21,"verse_start":9,"verse_end":9,"texts":{"pt":{"prompt":"O que clamavam as multidões que iam adiante de Jesus e as que o seguiam?","bible_ref":"Mateus 21:9","verse_text":"E as multidões que iam adiante, e as que seguiam, clamavam: Hosana ao Filho de Davi! Bendito o que vem no nome do Senhor! Hosana nas alturas!"},"fr":{"prompt":"Que criaient ceux qui précédaient et ceux qui suivaient Jésus ?","bible_ref":"Matthieu 21:9","verse_text":"Ceux qui précédaient et ceux qui suivaient Jésus criaient: Hosanna au Fils de David! Béni soit celui qui vient au nom du Seigneur! Hosanna dans les lieux très hauts!"},"en":{"prompt":"What did the multitudes that went before Jesus and that followed cry?","bible_ref":"Matthew 21:9","verse_text":"And the multitudes that went before, and that followed, cried, saying, Hosanna to the Son of David: Blessed is he that cometh in the name of the Lord; Hosanna in the highest."},"es":{"prompt":"¿Qué aclamaban las gentes que iban delante de Jesús y las que iban detrás?","bible_ref":"Mateo 21:9","verse_text":"Y las gentes que iban delante, y las que iban detrás, aclamaban diciendo: ¡Hosanna al Hijo de David! ¡Bendito el que viene en el nombre del Señor! ¡Hosanna en las alturas!"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Hosana!"},"fr":{"text":"Hosanna !"},"en":{"text":"Hosanna!"},"es":{"text":"¡Hosanna!"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Aleluia!"},"fr":{"text":"Alléluia !"},"en":{"text":"Hallelujah!"},"es":{"text":"¡Aleluya!"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Amém!"},"fr":{"text":"Amen !"},"en":{"text":"Amen!"},"es":{"text":"¡Amén!"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Maranata!"},"fr":{"text":"Maranatha !"},"en":{"text":"Maranatha!"},"es":{"text":"¡Maranatha!"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-easy-004","type":"choice","level":"easy","testament":"nt","book":"MAT","chapter":4,"verse_start":2,"verse_end":2,"texts":{"pt":{"prompt":"Quantos dias jejuou Jesus no deserto, antes de ter fome?","bible_ref":"Mateus 4:2","verse_text":"E depois de jejuar quarenta dias e quarenta noites, teve fome."},"fr":{"prompt":"Combien de jours Jésus jeûna-t-il avant d’avoir faim ?","bible_ref":"Matthieu 4:2","verse_text":"Après avoir jeûné quarante jours et quarante nuits, il eut faim."},"en":{"prompt":"How many days did Jesus fast before he was hungry?","bible_ref":"Matthew 4:2","verse_text":"And when he had fasted forty days and forty nights, he was afterward an hungred."},"es":{"prompt":"¿Cuántos días ayunó Jesús antes de tener hambre?","bible_ref":"Mateo 4:2","verse_text":"Y habiendo ayunado cuarenta días y cuarenta noches, después tuvo hambre."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Quarenta"},"fr":{"text":"Quarante"},"en":{"text":"Forty"},"es":{"text":"Cuarenta"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Três"},"fr":{"text":"Trois"},"en":{"text":"Three"},"es":{"text":"Tres"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Sete"},"fr":{"text":"Sept"},"en":{"text":"Seven"},"es":{"text":"Siete"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Doze"},"fr":{"text":"Douze"},"en":{"text":"Twelve"},"es":{"text":"Doce"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-easy-005","type":"choice","level":"easy","testament":"nt","book":"MRK","chapter":1,"verse_start":6,"verse_end":6,"texts":{"pt":{"prompt":"Segundo Marcos 1:6, o que comia João Batista?","bible_ref":"Marcos 1:6","verse_text":"João se vestia de pelos de camelo, e um cinto de couro em sua cintura; e comia gafanhotos e mel do campo."},"fr":{"prompt":"Selon Marc 1:6, de quoi se nourrissait Jean-Baptiste ?","bible_ref":"Marc 1:6","verse_text":"Jean avait un vêtement de poils de chameau, et une ceinture de cuir autour des reins. Il se nourrissait de sauterelles et de miel sauvage."},"en":{"prompt":"According to Mark 1:6, what did John the Baptist eat?","bible_ref":"Mark 1:6","verse_text":"And John was clothed with camel’s hair, and with a girdle of a skin about his loins; and he did eat locusts and wild honey;"},"es":{"prompt":"Según Marcos 1:6, ¿qué comía Juan el Bautista?","bible_ref":"Marcos 1:6","verse_text":"Y Juan andaba vestido de pelos de camello, y con un cinto de cuero alrededor de sus lomos; y comía langostas y miel silvestre."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Gafanhotos e mel do campo"},"fr":{"text":"Des sauterelles et du miel sauvage"},"en":{"text":"Locusts and wild honey"},"es":{"text":"Langostas y miel silvestre"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Pão e peixe"},"fr":{"text":"Du pain et du poisson"},"en":{"text":"Bread and fish"},"es":{"text":"Pan y peces"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Figos e uvas"},"fr":{"text":"Des figues et des raisins"},"en":{"text":"Figs and grapes"},"es":{"text":"Higos y uvas"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Maná e codornizes"},"fr":{"text":"De la manne et des cailles"},"en":{"text":"Manna and quails"},"es":{"text":"Maná y codornices"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-easy-006","type":"choice","level":"easy","testament":"nt","book":"MRK","chapter":4,"verse_start":38,"verse_end":38,"texts":{"pt":{"prompt":"No barco, os discípulos tinham medo de perecer. O que fazia Jesus?","bible_ref":"Marcos 4:38","verse_text":"Jesus estava na popa dormindo sobre uma almofada. Então despertaram-no, e disseram-lhe: Mestre, não te importas que pereçamos?"},"fr":{"prompt":"Dans la barque, les disciples avaient peur de périr. Que faisait Jésus ?","bible_ref":"Marc 4:38","verse_text":"Et lui, il dormait à la poupe sur le coussin. Ils le réveillèrent, et lui dirent: Maître, ne t’inquiètes-tu pas de ce que nous périssons?"},"en":{"prompt":"In the ship, the disciples were afraid they would perish. What was Jesus doing?","bible_ref":"Mark 4:38","verse_text":"And he was in the hinder part of the ship, asleep on a pillow: and they awake him, and say unto him, Master, carest thou not that we perish?"},"es":{"prompt":"En la barca, los discípulos temían perecer. ¿Qué hacía Jesús?","bible_ref":"Marcos 4:38","verse_text":"Y él estaba en la popa, durmiendo sobre un cabezal, y le despertaron, y le dicen: ¿Maestro, no tienes cuidado que perecemos?"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Dormia sobre uma almofada"},"fr":{"text":"Il dormait sur le coussin"},"en":{"text":"He was asleep on a pillow"},"es":{"text":"Dormía sobre un cabezal"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Remava com os discípulos"},"fr":{"text":"Il ramait avec les disciples"},"en":{"text":"He was rowing with the disciples"},"es":{"text":"Remaba con los discípulos"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Lançava as redes"},"fr":{"text":"Il jetait les filets"},"en":{"text":"He was casting the nets"},"es":{"text":"Echaba las redes"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Cantava um salmo"},"fr":{"text":"Il chantait un psaume"},"en":{"text":"He was singing a psalm"},"es":{"text":"Cantaba un salmo"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-easy-007","type":"choice","level":"easy","testament":"nt","book":"MRK","chapter":14,"verse_start":72,"verse_end":72,"texts":{"pt":{"prompt":"Depois de Pedro ter negado Jesus, que ave cantou?","bible_ref":"Marcos 14:72","verse_text":"O galo cantou a segunda vez. E Pedro se lembrou da palavra que Jesus havia lhe dito: “Antes que o galo cante duas vezes, tu me negarás três vezes.” Então ele retirou-se dali e chorou."},"fr":{"prompt":"Après que Pierre eut renié Jésus, quel oiseau chanta ?","bible_ref":"Marc 14:72","verse_text":"Aussitôt, pour la seconde fois, le coq chanta. Et Pierre se souvint de la parole que Jésus lui avait dite: Avant que le coq chante deux fois, tu me renieras trois fois. Et en y réfléchissant, il pleurait."},"en":{"prompt":"After Peter denied Jesus, which bird crew?","bible_ref":"Mark 14:72","verse_text":"And the second time the cock crew. And Peter called to mind the word that Jesus said unto him, Before the cock crow twice, thou shalt deny me thrice. And when he thought thereon, he wept."},"es":{"prompt":"Después de que Pedro negó a Jesús, ¿qué ave cantó?","bible_ref":"Marcos 14:72","verse_text":"Y el gallo cantó la segunda vez: y Pedro se acordó de las palabras que Jesús le había dicho: Antes que el gallo cante dos veces, me negarás tres veces. Y pensando en esto, lloraba."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O galo"},"fr":{"text":"Le coq"},"en":{"text":"The cock"},"es":{"text":"El gallo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Uma pomba"},"fr":{"text":"Une colombe"},"en":{"text":"A dove"},"es":{"text":"Una paloma"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um corvo"},"fr":{"text":"Un corbeau"},"en":{"text":"A raven"},"es":{"text":"Un cuervo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um pardal"},"fr":{"text":"Un passereau"},"en":{"text":"A sparrow"},"es":{"text":"Un pajarillo"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-easy-008","type":"choice","level":"easy","testament":"nt","book":"LUK","chapter":15,"verse_start":4,"verse_end":4,"texts":{"pt":{"prompt":"Na parábola da ovelha perdida, quantas ovelhas tinha o homem?","bible_ref":"Lucas 15:4","verse_text":"Quem de vós, tendo cem ovelhas, e perdendo uma delas, não deixa no deserto as noventa e nove, e vai em busca da perdida, até que a encontre?"},"fr":{"prompt":"Dans la parabole de la brebis perdue, combien de brebis l’homme avait-il ?","bible_ref":"Luc 15:4","verse_text":"Quel homme d’entre vous, s’il a cent brebis, et qu’il en perde une, ne laisse les quatre-vingt-dix-neuf autres dans le désert pour aller après celle qui est perdue, jusqu’à ce qu’il la retrouve?"},"en":{"prompt":"In the parable of the lost sheep, how many sheep did the man have?","bible_ref":"Luke 15:4","verse_text":"What man of you, having an hundred sheep, if he lose one of them, doth not leave the ninety and nine in the wilderness, and go after that which is lost, until he find it?"},"es":{"prompt":"En la parábola de la oveja perdida, ¿cuántas ovejas tenía el hombre?","bible_ref":"Lucas 15:4","verse_text":"¿Qué hombre de vosotros, teniendo cien ovejas, si perdiere una de ellas, no deja las noventa y nueve en el desierto, y va á la que se perdió, hasta que la halle?"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Cem"},"fr":{"text":"Cent"},"en":{"text":"An hundred"},"es":{"text":"Cien"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Dez"},"fr":{"text":"Dix"},"en":{"text":"Ten"},"es":{"text":"Diez"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Doze"},"fr":{"text":"Douze"},"en":{"text":"Twelve"},"es":{"text":"Doce"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Mil"},"fr":{"text":"Mille"},"en":{"text":"A thousand"},"es":{"text":"Mil"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-easy-009","type":"choice","level":"easy","testament":"nt","book":"LUK","chapter":1,"verse_start":31,"verse_end":31,"texts":{"pt":{"prompt":"Que nome devia Maria dar ao filho, segundo o anjo?","bible_ref":"Lucas 1:31","verse_text":"E eis que em teu ventre conceberás, darás à luz um filho, e chamarás o seu nome de Jesus."},"fr":{"prompt":"Selon l’ange, quel nom Marie devait-elle donner à son fils ?","bible_ref":"Luc 1:31","verse_text":"Et voici, tu deviendras enceinte, et tu enfanteras un fils, et tu lui donneras le nom de Jésus."},"en":{"prompt":"According to the angel, what name was Mary to give her son?","bible_ref":"Luke 1:31","verse_text":"And, behold, thou shalt conceive in thy womb, and bring forth a son, and shalt call his name JESUS."},"es":{"prompt":"Según el ángel, ¿qué nombre debía poner María a su hijo?","bible_ref":"Lucas 1:31","verse_text":"Y he aquí, concebirás en tu seno, y parirás un hijo, y llamarás su nombre JESUS."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Jesus"},"fr":{"text":"Jésus"},"en":{"text":"Jesus"},"es":{"text":"Jesús"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"João"},"fr":{"text":"Jean"},"en":{"text":"John"},"es":{"text":"Juan"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"José"},"fr":{"text":"Joseph"},"en":{"text":"Joseph"},"es":{"text":"José"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Samuel"},"fr":{"text":"Samuel"},"en":{"text":"Samuel"},"es":{"text":"Samuel"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-easy-010","type":"choice","level":"easy","testament":"nt","book":"LUK","chapter":18,"verse_start":10,"verse_end":10,"texts":{"pt":{"prompt":"Na parábola, aonde subiram o fariseu e o publicano para orar?","bible_ref":"Lucas 18:10","verse_text":"Dois homens subiram ao Templo para orar, um fariseu, e o outro publicano."},"fr":{"prompt":"Dans la parabole, où le pharisien et le publicain montèrent-ils pour prier ?","bible_ref":"Luc 18:10","verse_text":"Deux hommes montèrent au temple pour prier; l’un était pharisien, et l’autre publicain."},"en":{"prompt":"In the parable, where did the Pharisee and the publican go up to pray?","bible_ref":"Luke 18:10","verse_text":"Two men went up into the temple to pray; the one a Pharisee, and the other a publican."},"es":{"prompt":"En la parábola, ¿adónde subieron a orar el fariseo y el publicano?","bible_ref":"Lucas 18:10","verse_text":"Dos hombres subieron al templo á orar: el uno Fariseo, el otro publicano."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Ao templo"},"fr":{"text":"Au temple"},"en":{"text":"Into the temple"},"es":{"text":"Al templo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"A um monte"},"fr":{"text":"Sur une montagne"},"en":{"text":"Up a mountain"},"es":{"text":"A un monte"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Ao deserto"},"fr":{"text":"Au désert"},"en":{"text":"Into the wilderness"},"es":{"text":"Al desierto"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Ao telhado de uma casa"},"fr":{"text":"Sur le toit d’une maison"},"en":{"text":"Onto a housetop"},"es":{"text":"Al terrado de una casa"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-easy-011","type":"choice","level":"easy","testament":"nt","book":"LUK","chapter":15,"verse_start":8,"verse_end":8,"texts":{"pt":{"prompt":"Na parábola, quantas moedas tinha a mulher que perdeu uma e varreu a casa?","bible_ref":"Lucas 15:8","verse_text":"Ou que mulher, tendo dez moedas de prata, se perder a uma moeda, não acende a lâmpada, e varre a casa, e busca cuidadosamente até a achar?"},"fr":{"prompt":"Dans la parabole, combien de drachmes avait la femme qui en perdit une et balaya la maison ?","bible_ref":"Luc 15:8","verse_text":"Ou quelle femme, si elle a dix drachmes, et qu’elle en perde une, n’allume une lampe, ne balaie la maison, et ne cherche avec soin, jusqu’à ce qu’elle la retrouve?"},"en":{"prompt":"In the parable, how many pieces of silver had the woman who lost one and swept the house?","bible_ref":"Luke 15:8","verse_text":"Either what woman having ten pieces of silver, if she lose one piece, doth not light a candle, and sweep the house, and seek diligently till she find it?"},"es":{"prompt":"En la parábola, ¿cuántas dracmas tenía la mujer que perdió una y barrió la casa?","bible_ref":"Lucas 15:8","verse_text":"¿O qué mujer que tiene diez dracmas, si perdiere una dracma, no enciende el candil, y barre la casa, y busca con diligencia hasta hallarla?"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Dez"},"fr":{"text":"Dix"},"en":{"text":"Ten"},"es":{"text":"Diez"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Três"},"fr":{"text":"Trois"},"en":{"text":"Three"},"es":{"text":"Tres"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Sete"},"fr":{"text":"Sept"},"en":{"text":"Seven"},"es":{"text":"Siete"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Trinta"},"fr":{"text":"Trente"},"en":{"text":"Thirty"},"es":{"text":"Treinta"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-easy-012","type":"choice","level":"easy","testament":"nt","book":"JHN","chapter":1,"verse_start":29,"verse_end":29,"texts":{"pt":{"prompt":"Quando viu Jesus vir ter com ele, que nome lhe deu João?","bible_ref":"João 1:29","verse_text":"O dia seguinte viu João a Jesus vir a ele, e disse: Eis o Cordeiro de Deus, que tira o pecado do mundo."},"fr":{"prompt":"Quand Jean vit Jésus venir à lui, comment l’appela-t-il ?","bible_ref":"Jean 1:29","verse_text":"Le lendemain, il vit Jésus venant à lui, et il dit: Voici l’Agneau de Dieu, qui ôte le péché du monde."},"en":{"prompt":"When John saw Jesus coming unto him, what did he call him?","bible_ref":"John 1:29","verse_text":"The next day John seeth Jesus coming unto him, and saith, Behold the Lamb of God, which taketh away the sin of the world."},"es":{"prompt":"Cuando Juan vio a Jesús que venía a él, ¿cómo lo llamó?","bible_ref":"Juan 1:29","verse_text":"El siguiente día ve Juan á Jesús que venía á él, y dice: He aquí el Cordero de Dios, que quita el pecado del mundo."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O Cordeiro de Deus"},"fr":{"text":"L’Agneau de Dieu"},"en":{"text":"The Lamb of God"},"es":{"text":"El Cordero de Dios"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O Leão de Judá"},"fr":{"text":"Le Lion de Juda"},"en":{"text":"The Lion of Judah"},"es":{"text":"El León de Judá"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"O Filho de David"},"fr":{"text":"Le Fils de David"},"en":{"text":"The Son of David"},"es":{"text":"El Hijo de David"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"O Pastor de Israel"},"fr":{"text":"Le Berger d’Israël"},"en":{"text":"The Shepherd of Israel"},"es":{"text":"El Pastor de Israel"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-easy-013","type":"choice","level":"easy","testament":"nt","book":"JHN","chapter":20,"verse_start":25,"verse_end":25,"texts":{"pt":{"prompt":"O que disse Tomé que tinha de ver nas mãos de Jesus para crer?","bible_ref":"João 20:25","verse_text":"Disseram-lhe pois os outros discípulos: Vimos ao Senhor. Porém ele lhes disse: Se em suas mãos não vir o sinal dos cravos, e não pôr meu dedo no lugar dos cravos, e não pôr minha mão em seu lado, em maneira nenhuma crerei."},"fr":{"prompt":"Que Thomas dit-il devoir voir dans les mains de Jésus pour croire ?","bible_ref":"Jean 20:25","verse_text":"Les autres disciples lui dirent donc: Nous avons vu le Seigneur. Mais il leur dit: Si je ne vois dans ses mains la marque des clous, et si je ne mets mon doigt dans la marque des clous, et si je ne mets ma main dans son côté, je ne croirai point."},"en":{"prompt":"What did Thomas say he must see in Jesus’ hands before he would believe?","bible_ref":"John 20:25","verse_text":"The other disciples therefore said unto him, We have seen the Lord. But he said unto them, Except I shall see in his hands the print of the nails, and put my finger into the print of the nails, and thrust my hand into his side, I will not believe."},"es":{"prompt":"¿Qué dijo Tomás que tenía que ver en las manos de Jesús para creer?","bible_ref":"Juan 20:25","verse_text":"Dijéronle pues los otros discípulos: Al Señor hemos visto. Y él les dijo: Si no viere en sus manos la señal de los clavos, y metiere mi dedo en el lugar de los clavos, y metiere mi mano en su costado, no creeré."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O sinal dos cravos"},"fr":{"text":"La marque des clous"},"en":{"text":"The print of the nails"},"es":{"text":"La señal de los clavos"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Pão partido"},"fr":{"text":"Du pain rompu"},"en":{"text":"Broken bread"},"es":{"text":"Pan partido"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Uma luz"},"fr":{"text":"Une lumière"},"en":{"text":"A light"},"es":{"text":"Una luz"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um anel de ouro"},"fr":{"text":"Un anneau d’or"},"en":{"text":"A ring of gold"},"es":{"text":"Un anillo de oro"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-easy-014","type":"choice","level":"easy","testament":"nt","book":"JHN","chapter":6,"verse_start":9,"verse_end":9,"texts":{"pt":{"prompt":"Quem tinha os cinco pães de cevada e os dois peixinhos?","bible_ref":"João 6:9","verse_text":"Um menino está aqui que tem cinco pães de cevada e dois peixinhos; mas que é isto entre tantos?"},"fr":{"prompt":"Qui avait les cinq pains d’orge et les deux poissons ?","bible_ref":"Jean 6:9","verse_text":"Il y a ici un jeune garçon qui a cinq pains d’orge et deux poissons; mais qu’est-ce que cela pour tant de gens?"},"en":{"prompt":"Who had the five barley loaves and the two small fishes?","bible_ref":"John 6:9","verse_text":"There is a lad here, which hath five barley loaves, and two small fishes: but what are they among so many?"},"es":{"prompt":"¿Quién tenía los cinco panes de cebada y los dos pececillos?","bible_ref":"Juan 6:9","verse_text":"Un muchacho está aquí que tiene cinco panes de cebada y dos pececillos; ¿mas qué es esto entre tantos?"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Um menino"},"fr":{"text":"Un jeune garçon"},"en":{"text":"A lad"},"es":{"text":"Un muchacho"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Uma viúva"},"fr":{"text":"Une veuve"},"en":{"text":"A widow"},"es":{"text":"Una viuda"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um soldado romano"},"fr":{"text":"Un soldat romain"},"en":{"text":"A Roman soldier"},"es":{"text":"Un soldado romano"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um pescador idoso"},"fr":{"text":"Un vieux pêcheur"},"en":{"text":"An old fisherman"},"es":{"text":"Un pescador anciano"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-easy-015","type":"choice","level":"easy","testament":"nt","book":"JHN","chapter":19,"verse_start":2,"verse_end":2,"texts":{"pt":{"prompt":"O que puseram os soldados sobre a cabeça de Jesus?","bible_ref":"João 19:2","verse_text":"E trançando os soldados uma coroa de espinhos, puseram-na sobre sua cabeça, e o vestiram de uma roupa vermelha."},"fr":{"prompt":"Que posèrent les soldats sur la tête de Jésus ?","bible_ref":"Jean 19:2","verse_text":"Les soldats tressèrent une couronne d’épines qu’ils posèrent sur sa tête, et ils le revêtirent d’un manteau de pourpre; puis, s’approchant de lui,"},"en":{"prompt":"What did the soldiers put on Jesus’ head?","bible_ref":"John 19:2","verse_text":"And the soldiers platted a crown of thorns, and put it on his head, and they put on him a purple robe,"},"es":{"prompt":"¿Qué pusieron los soldados sobre la cabeza de Jesús?","bible_ref":"Juan 19:2","verse_text":"Y los soldados entretejieron de espinas una corona, y pusiéronla sobre su cabeza, y le vistieron de una ropa de grana;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Uma coroa de espinhos"},"fr":{"text":"Une couronne d’épines"},"en":{"text":"A crown of thorns"},"es":{"text":"Una corona de espinas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Uma coroa de ouro"},"fr":{"text":"Une couronne d’or"},"en":{"text":"A crown of gold"},"es":{"text":"Una corona de oro"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um capacete"},"fr":{"text":"Un casque"},"en":{"text":"A helmet"},"es":{"text":"Un yelmo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Uma grinalda de flores"},"fr":{"text":"Une guirlande de fleurs"},"en":{"text":"A garland of flowers"},"es":{"text":"Una guirnalda de flores"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-easy-016","type":"choice","level":"easy","testament":"nt","book":"ACT","chapter":16,"verse_start":26,"verse_end":26,"texts":{"pt":{"prompt":"O que aconteceu de repente, abrindo todas as portas da prisão?","bible_ref":"Atos 16:26","verse_text":"E de repente houve um terremoto tão grande que os alicerces da prisão se moviam; e logo todas as portas se abriram, e todas as correntes que prendiam a todos se soltaram."},"fr":{"prompt":"Que se passa-t-il tout à coup, si bien que toutes les portes de la prison s’ouvrirent ?","bible_ref":"Actes 16:26","verse_text":"Tout à coup il se fit un grand tremblement de terre, en sorte que les fondements de la prison furent ébranlés; au même instant, toutes les portes s’ouvrirent, et les liens de tous les prisonniers furent rompus."},"en":{"prompt":"What happened suddenly, so that all the prison doors were opened?","bible_ref":"Acts 16:26","verse_text":"And suddenly there was a great earthquake, so that the foundations of the prison were shaken: and immediately all the doors were opened, and every one’s bands were loosed."},"es":{"prompt":"¿Qué ocurrió de repente, de modo que todas las puertas de la cárcel se abrieron?","bible_ref":"Hechos 16:26","verse_text":"Entonces fué hecho de repente un gran terremoto, de tal manera que los cimientos de la cárcel se movían; y luego todas las puertas se abrieron, y las prisiones de todos se soltaron."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Um grande terramoto"},"fr":{"text":"Un grand tremblement de terre"},"en":{"text":"A great earthquake"},"es":{"text":"Un gran terremoto"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um incêndio"},"fr":{"text":"Un incendie"},"en":{"text":"A fire"},"es":{"text":"Un incendio"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Uma tempestade"},"fr":{"text":"Une tempête"},"en":{"text":"A storm"},"es":{"text":"Una tempestad"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Uma inundação"},"fr":{"text":"Une inondation"},"en":{"text":"A flood"},"es":{"text":"Una inundación"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-easy-017","type":"choice","level":"easy","testament":"nt","book":"ACT","chapter":2,"verse_start":2,"verse_end":2,"texts":{"pt":{"prompt":"Em Atos 2:2, que ruído veio de repente do céu e encheu a casa?","bible_ref":"Atos 2:2","verse_text":"E de repente houve um ruído do céu, como de um vento forte e violento, e encheu toda a casa onde eles estavam sentados."},"fr":{"prompt":"En Actes 2:2, quel bruit vint tout à coup du ciel et remplit la maison ?","bible_ref":"Actes 2:2","verse_text":"Tout à coup il vint du ciel un bruit comme celui d’un vent impétueux, et il remplit toute la maison où ils étaient assis."},"en":{"prompt":"In Acts 2:2, what sound suddenly came from heaven and filled the house?","bible_ref":"Acts 2:2","verse_text":"And suddenly there came a sound from heaven as of a rushing mighty wind, and it filled all the house where they were sitting."},"es":{"prompt":"En Hechos 2:2, ¿qué estruendo vino de repente del cielo y llenó la casa?","bible_ref":"Hechos 2:2","verse_text":"Y de repente vino un estruendo del cielo como de un viento recio que corría, el cual hinchió toda la casa donde estaban sentados;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Como de um vento forte"},"fr":{"text":"Comme celui d’un vent impétueux"},"en":{"text":"As of a rushing mighty wind"},"es":{"text":"Como de un viento recio"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Como de um trovão"},"fr":{"text":"Comme celui du tonnerre"},"en":{"text":"As of thunder"},"es":{"text":"Como de un trueno"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Como de trombetas"},"fr":{"text":"Comme celui de trompettes"},"en":{"text":"As of trumpets"},"es":{"text":"Como de trompetas"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Como de um rio"},"fr":{"text":"Comme celui d’un fleuve"},"en":{"text":"As of a river"},"es":{"text":"Como de un río"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-easy-018","type":"choice","level":"easy","testament":"nt","book":"ACT","chapter":5,"verse_start":15,"verse_end":15,"texts":{"pt":{"prompt":"Punham os doentes nas ruas, na esperança de que, ao passar Pedro, alguma coisa dele os cobrisse. O quê?","bible_ref":"Atos 5:15","verse_text":"De maneira que traziam os enfermos às ruas, e os botavam em camas e macas, para que, vindo Pedro, pelo menos a sombra dele cobrisse a alguns deles."},"fr":{"prompt":"On plaçait les malades dans les rues, dans l’espoir que, au passage de Pierre, quelque chose de lui les couvrît. Quoi ?","bible_ref":"Actes 5:15","verse_text":"en sorte qu’on apportait les malades dans les rues et qu’on les plaçait sur des lits et des couchettes, afin que, lorsque Pierre passerait, son ombre au moins couvrît quelqu’un d’eux."},"en":{"prompt":"The sick were laid in the streets, so that something of Peter might overshadow them as he passed by. What was it?","bible_ref":"Acts 5:15","verse_text":"Insomuch that they brought forth the sick into the streets, and laid them on beds and couches, that at the least the shadow of Peter passing by might overshadow some of them."},"es":{"prompt":"Ponían a los enfermos en las calles, para que al pasar Pedro algo de él los alcanzase. ¿Qué era?","bible_ref":"Hechos 5:15","verse_text":"Tanto que echaban los enfermos por las calles, y los ponían en camas y en lechos, para que viniendo Pedro, á lo menos su sombra tocase á alguno de ellos."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"A sua sombra"},"fr":{"text":"Son ombre"},"en":{"text":"His shadow"},"es":{"text":"Su sombra"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O seu manto"},"fr":{"text":"Son manteau"},"en":{"text":"His mantle"},"es":{"text":"Su manto"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"A sua mão"},"fr":{"text":"Sa main"},"en":{"text":"His hand"},"es":{"text":"Su mano"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"O seu bordão"},"fr":{"text":"Son bâton"},"en":{"text":"His staff"},"es":{"text":"Su bordón"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-easy-019","type":"order","level":"easy","testament":"nt","book":"MAT","chapter":2,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Ordena estes episódios de Mateus pela ordem em que aconteceram.","bible_ref":"Mateus 2:1","verse_text":null},"fr":{"prompt":"Mets ces épisodes de Matthieu dans l’ordre où ils se sont produits.","bible_ref":"Matthieu 2:1","verse_text":null},"en":{"prompt":"Put these episodes from Matthew in the order they happened.","bible_ref":"Matthew 2:1","verse_text":null},"es":{"prompt":"Ordena estos episodios de Mateo según ocurrieron.","bible_ref":"Mateo 2:1","verse_text":null}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"Uns magos do oriente chegam a Jerusalém","ref":"Mateus 2:1"},"fr":{"text":"Des mages d’Orient arrivent à Jérusalem","ref":"Matthieu 2:1"},"en":{"text":"Wise men from the east come to Jerusalem","ref":"Matthew 2:1"},"es":{"text":"Unos magos del oriente llegan a Jerusalem","ref":"Mateo 2:1"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Os magos adoram o menino","ref":"Mateus 2:11"},"fr":{"text":"Les mages adorent le petit enfant","ref":"Matthieu 2:11"},"en":{"text":"The wise men worship the young child","ref":"Matthew 2:11"},"es":{"text":"Los magos adoran al niño","ref":"Mateo 2:11"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Avisados em sonho, os magos regressam por outro caminho","ref":"Mateus 2:12"},"fr":{"text":"Avertis en songe, les mages s’en retournent par un autre chemin","ref":"Matthieu 2:12"},"en":{"text":"Warned in a dream, the wise men depart another way","ref":"Matthew 2:12"},"es":{"text":"Avisados en sueños, los magos se vuelven por otro camino","ref":"Mateo 2:12"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"A família vai morar em Nazaré","ref":"Mateus 2:23"},"fr":{"text":"La famille va demeurer à Nazareth","ref":"Matthieu 2:23"},"en":{"text":"The family goes to dwell in Nazareth","ref":"Matthew 