select public.upsert_bank_question($json${"id":"evan2-easy-020","type":"order","level":"easy","testament":"nt","book":"MAT","chapter":14,"verse_start":10,"verse_end":10,"texts":{"pt":{"prompt":"Ordena estes episódios de Mateus pela ordem em que aconteceram.","bible_ref":"Mateus 14:10","verse_text":null},"fr":{"prompt":"Mets ces épisodes de Matthieu dans l’ordre où ils se sont produits.","bible_ref":"Matthieu 14:10","verse_text":null},"en":{"prompt":"Put these episodes from Matthew in the order they happened.","bible_ref":"Matthew 14:10","verse_text":null},"es":{"prompt":"Ordena estos episodios de Mateo según ocurrieron.","bible_ref":"Mateo 14:10","verse_text":null}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"João Batista é degolado na prisão","ref":"Mateus 14:10"},"fr":{"text":"Jean-Baptiste est décapité dans la prison","ref":"Matthieu 14:10"},"en":{"text":"John the Baptist is beheaded in the prison","ref":"Matthew 14:10"},"es":{"text":"Juan el Bautista es degollado en la cárcel","ref":"Mateo 14:10"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Jesus retira-se de barco para um lugar deserto","ref":"Mateus 14:13"},"fr":{"text":"Jésus se retire dans une barque vers un lieu désert","ref":"Matthieu 14:13"},"en":{"text":"Jesus departs by ship into a desert place","ref":"Matthew 14:13"},"es":{"text":"Jesús se retira en un barco a un lugar desierto","ref":"Mateo 14:13"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Jesus tem compaixão da multidão e cura os doentes","ref":"Mateus 14:14"},"fr":{"text":"Jésus a compassion de la foule et guérit les malades","ref":"Matthieu 14:14"},"en":{"text":"Jesus has compassion on the multitude and heals their sick","ref":"Matthew 14:14"},"es":{"text":"Jesús tiene compasión de la multitud y sana a los enfermos","ref":"Mateo 14:14"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Os que tocam a borda da roupa de Jesus ficam curados","ref":"Mateus 14:36"},"fr":{"text":"Ceux qui touchent le bord de son vêtement sont guéris","ref":"Matthieu 14:36"},"en":{"text":"As many as touch the hem of his garment are made whole","ref":"Matthew 14:36"},"es":{"text":"Los que tocan el borde de su manto quedan sanos","ref":"Mateo 14:36"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-easy-021","type":"order","level":"easy","testament":"nt","book":"MRK","chapter":10,"verse_start":16,"verse_end":16,"texts":{"pt":{"prompt":"Ordena estes episódios de Marcos pela ordem em que aconteceram.","bible_ref":"Marcos 10:16","verse_text":null},"fr":{"prompt":"Mets ces épisodes de Marc dans l’ordre où ils se sont produits.","bible_ref":"Marc 10:16","verse_text":null},"en":{"prompt":"Put these episodes from Mark in the order they happened.","bible_ref":"Mark 10:16","verse_text":null},"es":{"prompt":"Ordena estos episodios de Marcos según ocurrieron.","bible_ref":"Marcos 10:16","verse_text":null}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"Jesus toma as crianças nos braços e abençoa-as","ref":"Marcos 10:16"},"fr":{"text":"Jésus prend les enfants dans ses bras et les bénit","ref":"Marc 10:16"},"en":{"text":"Jesus takes the children in his arms and blesses them","ref":"Mark 10:16"},"es":{"text":"Jesús toma a los niños en los brazos y los bendice","ref":"Marcos 10:16"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Tiago e João vêm pedir um favor a Jesus","ref":"Marcos 10:35"},"fr":{"text":"Jacques et Jean viennent demander une faveur à Jésus","ref":"Marc 10:35"},"en":{"text":"James and John come to ask a favour of Jesus","ref":"Mark 10:35"},"es":{"text":"Jacobo y Juan vienen a pedir un favor a Jesús","ref":"Marcos 10:35"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um cego clama a Jesus em Jericó","ref":"Marcos 10:46-47"},"fr":{"text":"Un aveugle crie vers Jésus à Jéricho","ref":"Marc 10:46-47"},"en":{"text":"A blind man cries out to Jesus at Jericho","ref":"Mark 10:46-47"},"es":{"text":"Un ciego clama a Jesús en Jericó","ref":"Marcos 10:46-47"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Jesus diz: «Dai a César o que é de César»","ref":"Marcos 12:17"},"fr":{"text":"Jésus dit : « Rendez à César ce qui est à César »","ref":"Marc 12:17"},"en":{"text":