select public.upsert_bank_question($json${"id":"evan2-medium-001","type":"choice","level":"medium","testament":"nt","book":"MAT","chapter":13,"verse_start":45,"verse_end":46,"texts":{"pt":{"prompt":"Na parábola, o que encontrou o negociante que buscava boas pérolas?","bible_ref":"Mateus 13:45-46","verse_text":"O Reino dos céus também é semelhante a um homem negociante, que buscava boas pérolas. Quando este achou uma pérola de grande valor, foi, vendeu tudo quanto tinha, e a comprou."},"fr":{"prompt":"Dans la parabole, qu’a trouvé le marchand qui cherchait de belles perles ?","bible_ref":"Matthieu 13:45-46","verse_text":"Le royaume des cieux est encore semblable à un marchand qui cherche de belles perles. Il a trouvé une perle de grand prix; et il est allé vendre tout ce qu’il avait, et l’a achetée."},"en":{"prompt":"In the parable, what did the merchant man seeking goodly pearls find?","bible_ref":"Matthew 13:45-46","verse_text":"Again, the kingdom of heaven is like unto a merchant man, seeking goodly pearls: Who, when he had found one pearl of great price, went and sold all that he had, and bought it."},"es":{"prompt":"En la parábola, ¿qué halló el hombre tratante que buscaba buenas perlas?","bible_ref":"Mateo 13:45-46","verse_text":"También el reino de los cielos es semejante al hombre tratante, que busca buenas perlas; Que hallando una preciosa perla, fué y vendió todo lo que tenía, y la compró."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Uma pérola de grande valor"},"fr":{"text":"Une perle de grand prix"},"en":{"text":"One pearl of great price"},"es":{"text":"Una preciosa perla"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um tesouro escondido num campo"},"fr":{"text":"Un trésor caché dans un champ"},"en":{"text":"A treasure hid in a field"},"es":{"text":"Un tesoro escondido en un campo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Uma moeda perdida"},"fr":{"text":"Une drachme perdue"},"en":{"text":"A lost piece of silver"},"es":{"text":"Una dracma perdida"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Uma rede cheia de peixes"},"fr":{"text":"Un filet plein de poissons"},"en":{"text":"A net full of fishes"},"es":{"text":"Una red llena de peces"}}}]}$json$::jsonb);
