select public.upsert_bank_question($json${"id":"evan2-medium-003","type":"choice","level":"medium","testament":"nt","book":"MAT","chapter":18,"verse_start":22,"verse_end":22,"texts":{"pt":{"prompt":"Segundo Mateus 18:22, até quantas vezes disse Jesus que se deve perdoar?","bible_ref":"Mateus 18:22","verse_text":"Jesus lhe respondeu: Eu não te digo até sete, mas sim até setenta vezes sete."},"fr":{"prompt":"Selon Matthieu 18:22, jusqu’à combien de fois Jésus dit-il qu’il faut pardonner ?","bible_ref":"Matthieu 18:22","verse_text":"Jésus lui dit: Je ne te dis pas jusqu’à sept fois, mais jusqu’à septante fois sept fois."},"en":{"prompt":"According to Matthew 18:22, until how many times did Jesus say we should forgive?","bible_ref":"Matthew 18:22","verse_text":"Jesus saith unto him, I say not unto thee, Until seven times: but, Until seventy times seven."},"es":{"prompt":"Según Mateo 18:22, ¿hasta cuántas veces dijo Jesús que se debe perdonar?","bible_ref":"Mateo 18:22","verse_text":"Jesús le dice: No te digo hasta siete, mas aun hasta setenta veces siete."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Até setenta vezes sete"},"fr":{"text":"Jusqu’à septante fois sept fois"},"en":{"text":"Until seventy times seven"},"es":{"text":"Hasta setenta veces siete"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Até sete vezes"},"fr":{"text":"Jusqu’à sept fois"},"en":{"text":"Until seven times"},"es":{"text":"Hasta siete veces"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Até três vezes"},"fr":{"text":"Jusqu’à trois fois"},"en":{"text":"Until three times"},"es":{"text":"Hasta tres veces"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Até doze vezes"},"fr":{"text":"Jusqu’à douze fois"},"en":{"text":"Until twelve times"},"es":{"text":"Hasta doce veces"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-medium-004","type":"choice","level":"medium","testament":"nt","book":"MAT","chapter":17,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Quando Jesus foi transfigurado, quem apareceu a falar com ele?","bible_ref":"Mateus 17:3","verse_text":"E eis que lhes apareceram Moisés e Elias, falando com ele."},"fr":{"prompt":"Quand Jésus fut transfiguré, qui apparut, s’entretenant avec lui ?","bible_ref":"Matthieu 17:3","verse_text":"Et voici, Moïse et Élie leur apparurent, s’entretenant avec lui."},"en":{"prompt":"When Jesus was transfigured, who appeared talking with him?","bible_ref":"Matthew 17:3","verse_text":"And, behold, there appeared unto them Moses and Elias talking with him."},"es":{"prompt":"Cuando Jesús se transfiguró, ¿quiénes aparecieron hablando con él?","bible_ref":"Mateo 17:3","verse_text":"Y he aquí les aparecieron Moisés y Elías, hablando con él."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Moisés e Elias"},"fr":{"text":"Moïse et Élie"},"en":{"text":"Moses and Elias"},"es":{"text":"Moisés y Elías"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Abraão e Isaque"},"fr":{"text":"Abraham et Isaac"},"en":{"text":"Abraham and Isaac"},"es":{"text":"Abraham e Isaac"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"David e Salomão"},"fr":{"text":"David et Salomon"},"en":{"text":"David and Solomon"},"es":{"text":"David y Salomón"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Josué e Calebe"},"fr":{"text":"Josué et Caleb"},"en":{"text":"Joshua and Caleb"},"es":{"text":"Josué y Caleb"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-medium-005","type":"choice","level":"medium","testament":"nt","book":"MAT","chapter":27,"verse_start":24,"verse_end":24,"texts":{"pt":{"prompt":"O que fez Pilatos diante da multidão, dizendo que estava inocente do sangue daquele justo?","bible_ref":"Mateus 27:24","verse_text":"Quando, pois, Pilatos viu que nada adiantava, em vez disso se fazia mais tumulto, ele pegou água, lavou as mãos diante da multidão, e disse: Estou inocente do sangue deste justo. A responsabilidade é vossa."},"fr":{"prompt":"Que fit Pilate en présence de la foule, en disant qu’il était innocent du sang de ce juste ?","bible_ref":"Matthieu 27:24","verse_text":"Pilate, voyant qu’il ne gagnait rien, mais que le tumulte augmentait, prit de l’eau, se lava les mains en présence de la foule, et dit: Je suis innocent du sang de ce juste. Cela vous regarde."},"en":{"prompt":"What did Pilate do before the multitude, saying he was innocent of the blood of that just person?","bible_ref":"Matthew 27:24","verse_text":"When Pilate saw that he could prevail nothing, but that rather a tumult was made, he took water, and washed his hands before the multitude, saying, I am innocent of the blood of this just person: see ye to it."},"es":{"prompt":"¿Qué hizo Pilato delante del pueblo, diciendo que era inocente de la sangre de aquel justo?","bible_ref":"Mateo 27:24","verse_text":"Y viendo Pilato que nada adelantaba, antes se hacía más alboroto, tomando agua se lavó las manos delante del pueblo, diciendo: Inocente soy yo de la sangre de este justo: veréislo vosotros."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Lavou as mãos"},"fr":{"text":"Il se lava les mains"},"en":{"text":"He washed his hands"},"es":{"text":"Se lavó las manos"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Rasgou as suas vestes"},"fr":{"text":"Il déchira ses vêtements"},"en":{"text":"He rent his clothes"},"es":{"text":"Rasgó sus vestidos"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Ajoelhou-se"},"fr":{"text":"Il s’agenouilla"},"en":{"text":"He knelt down"},"es":{"text":"Se arrodilló"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Partiu o seu bastão"},"fr":{"text":"Il brisa son bâton"},"en":{"text":"He broke his staff"},"es":{"text":"Quebró su bastón"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-medium-006","type":"choice","level":"medium","testament":"nt","book":"MRK","chapter":12,"verse_start":42,"verse_end":42,"texts":{"pt":{"prompt":"O que deitou na arca do tesouro a pobre viúva que Jesus viu?","bible_ref":"Marcos 12:42","verse_text":"E uma pobre viúva veio, e lançou duas pequenas moedas, de pouco valor."},"fr":{"prompt":"Qu’a mis dans le tronc la pauvre veuve que Jésus a vue ?","bible_ref":"Marc 12:42","verse_text":"Il vint aussi une pauvre veuve, elle y mit deux petites pièces, faisant un quart de sou."},"en":{"prompt":"What did the poor widow whom Jesus saw throw into the treasury?","bible_ref":"Mark 12:42","verse_text":"And there came a certain poor widow, and she threw in two mites, which make a farthing."},"es":{"prompt":"¿Qué echó en el arca la viuda pobre que vio Jesús?","bible_ref":"Marcos 12:42","verse_text":"Y como vino una viuda pobre, echó dos blancas, que son un maravedí."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Duas pequenas moedas"},"fr":{"text":"Deux petites pièces"},"en":{"text":"Two mites"},"es":{"text":"Dos blancas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Uma moeda de ouro"},"fr":{"text":"Une pièce d’or"},"en":{"text":"A piece of gold"},"es":{"text":"Una moneda de oro"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Trinta moedas de prata"},"fr":{"text":"Trente pièces d’argent"},"en":{"text":"Thirty pieces of silver"},"es":{"text":"Treinta piezas de plata"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um talento"},"fr":{"text":"Un talent"},"en":{"text":"A talent"},"es":{"text":"Un talento"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-medium-007","type":"choice","level":"medium","testament":"nt","book":"MRK","chapter":6,"verse_start":7,"verse_end":7,"texts":{"pt":{"prompt":"Segundo Marcos 6:7, como começou Jesus a enviar os doze?","bible_ref":"Marcos 6:7","verse_text":"E chamou a si os doze, e começou a enviar de dois em dois; e deu-lhes poder sobre os espíritos imundos."},"fr":{"prompt":"Selon Marc 6:7, comment Jésus commença-t-il à envoyer les douze ?","bible_ref":"Marc 6:7","verse_text":"Alors il appela les douze, et il commença à les envoyer deux à deux, en leur donnant pouvoir sur les esprits impurs."},"en":{"prompt":"According to Mark 6:7, how did Jesus begin to send forth the twelve?","bible_ref":"Mark 6:7","verse_text":"And he called unto him the twelve, and began to send them forth by two and two; and gave them power over unclean spirits;"},"es":{"prompt":"Según Marcos 6:7, ¿cómo comenzó Jesús a enviar a los doce?","bible_ref":"Marcos 6:7","verse_text":"Y llamó á los doce, y comenzó á enviarlos de dos en dos: y les dió potestad sobre los espíritus inmundos."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"De dois em dois"},"fr":{"text":"Deux à deux"},"en":{"text":"By two and two"},"es":{"text":"De dos en dos"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um a um"},"fr":{"text":"Un par un"},"en":{"text":"One by one"},"es":{"text":"De uno en uno"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Todos juntos"},"fr":{"text":"Tous ensemble"},"en":{"text":"All together"},"es":{"text":"Todos juntos"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"De três em três"},"fr":{"text":"Trois par trois"},"en":{"text":"By three and three"},"es":{"text":"De tres en tres"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-medium-008","type":"choice","level":"medium","testament":"nt","book":"MRK","chapter":10,"verse_start":21,"verse_end":21,"texts":{"pt":{"prompt":"Jesus olhou para o homem que lhe perguntava pela vida eterna e amou-o. O que lhe disse para fazer?","bible_ref":"Marcos 10:21","verse_text":"E olhando Jesus para ele, amou-o, e disse-lhe: Uma coisa te falta: vai, vende tudo quanto tens, e dá aos pobres; e terás um tesouro no céu; e vem, segue-me, toma tua cruz."},"fr":{"prompt":"Jésus regarda l’homme qui l’interrogeait sur la vie éternelle et l’aima. Que lui dit-il de faire ?","bible_ref":"Marc 10:21","verse_text":"Jésus, l’ayant regardé, l’aima, et lui dit: Il te manque une chose; va, vends tout ce que tu as, donne-le aux pauvres, et tu auras un trésor dans le ciel. Puis viens, et suis-moi."},"en":{"prompt":"Jesus beheld the man asking about eternal life and loved him. What did he tell him to do?","bible_ref":"Mark 10:21","verse_text":"Then Jesus beholding him loved him, and said unto him, One thing thou lackest: go thy way, sell whatsoever thou hast, and give to the poor, and thou shalt have treasure in heaven: and come, take up the cross, and follow me."},"es":{"prompt":"Jesús miró al hombre que le preguntaba por la vida eterna y lo amó. ¿Qué le dijo que hiciera?","bible_ref":"Marcos 10:21","verse_text":"Entonces Jesús mirándole, amóle, y díjole: Una cosa te falta: ve, vende todo lo que tienes, y da á los pobres, y tendrás tesoro en el cielo; y ven, sígueme, tomando tu cruz."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Vender tudo e dar aos pobres"},"fr":{"text":"Vendre tout et le donner aux pauvres"},"en":{"text":"Sell all and give to the poor"},"es":{"text":"Venderlo todo y darlo a los pobres"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Oferecer um cordeiro no templo"},"fr":{"text":"Offrir un agneau au temple"},"en":{"text":"Offer a lamb in the temple"},"es":{"text":"Ofrecer un cordero en el templo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Jejuar quarenta dias"},"fr":{"text":"Jeûner quarante jours"},"en":{"text":"Fast forty days"},"es":{"text":"Ayunar cuarenta días"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Ir mostrar-se ao sacerdote"},"fr":{"text":"Aller se montrer au sacrificateur"},"en":{"text":"Go and shew himself to the priest"},"es":{"text":"Ir a mostrarse al sacerdote"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-medium-009","type":"choice","level":"medium","testament":"nt","book":"MRK","chapter":15,"verse_start":17,"verse_end":17,"texts":{"pt":{"prompt":"Segundo Marcos 15:17, de que cor vestiram a Jesus antes de lhe porem a coroa de espinhos?","bible_ref":"Marcos 15:17","verse_text":"E o vestiram de púrpura; teceram uma coroa de espinhos, e puseram nele."},"fr":{"prompt":"Selon Marc 15:17, de quelle couleur revêtit-on Jésus avant de lui mettre la couronne d’épines ?","bible_ref":"Marc 15:17","verse_text":"Ils le revêtirent de pourpre, et posèrent sur sa tête une couronne d’épines, qu’ils avaient tressée."},"en":{"prompt":"According to Mark 15:17, with what colour was Jesus clothed before the crown of thorns was put on him?","bible_ref":"Mark 15:17","verse_text":"And they clothed him with purple, and platted a crown of thorns, and put it about his head,"},"es":{"prompt":"Según Marcos 15:17, ¿de qué color vistieron a Jesús antes de ponerle la corona de espinas?","bible_ref":"Marcos 15:17","verse_text":"Y le visten de púrpura; y poniéndole una corona tejida de espinas,"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Púrpura"},"fr":{"text":"De pourpre"},"en":{"text":"Purple"},"es":{"text":"Púrpura"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Amarelo"},"fr":{"text":"De jaune"},"en":{"text":"Yellow"},"es":{"text":"Amarillo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Preto"},"fr":{"text":"De noir"},"en":{"text":"Black"},"es":{"text":"Negro"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Verde"},"fr":{"text":"De vert"},"en":{"text":"Green"},"es":{"text":"Verde"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-medium-010","type":"choice","level":"medium","testament":"nt","book":"LUK","chapter":15,"verse_start":15,"verse_end":15,"texts":{"pt":{"prompt":"Na parábola do filho pródigo, para que foi ele mandado aos campos?","bible_ref":"Lucas 15:15","verse_text":"E foi, se chegou a um dos cidadãos daquela terra; e este o mandou a seus campos para alimentar porcos."},"fr":{"prompt":"Dans la parabole du fils prodigue, pour quoi fut-il envoyé dans les champs ?","bible_ref":"Luc 15:15","verse_text":"Il alla se mettre au service d’un des habitants du pays, qui l’envoya dans ses champs garder les pourceaux."},"en":{"prompt":"In the parable of the prodigal son, what was he sent into the fields to do?","bible_ref":"Luke 15:15","verse_text":"And he went and joined himself to a citizen of that country; and he sent him into his fields to feed swine."},"es":{"prompt":"En la parábola del hijo pródigo, ¿para qué fue enviado al campo?","bible_ref":"Lucas 15:15","verse_text":"Y fué y se llegó á uno de los ciudadanos de aquella tierra, el cual le envió á su hacienda para que apacentase los puercos."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Alimentar porcos"},"fr":{"text":"Garder les pourceaux"},"en":{"text":"Feed swine"},"es":{"text":"Apacentar los puercos"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Guardar ovelhas"},"fr":{"text":"Garder les brebis"},"en":{"text":"Keep sheep"},"es":{"text":"Apacentar ovejas"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Colher uvas"},"fr":{"text":"Cueillir les raisins"},"en":{"text":"Gather grapes"},"es":{"text":"Vendimiar"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Lavrar a terra"},"fr":{"text":"Labourer la terre"},"en":{"text":"Plough the land"},"es":{"text":"Arar la tierra"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-medium-011","type":"choice","level":"medium","testament":"nt","book":"LUK","chapter":10,"verse_start":39,"verse_end":39,"texts":{"pt":{"prompt":"Em casa de Marta, o que fazia a sua irmã Maria?","bible_ref":"Lucas 10:39","verse_text":"E esta tinha uma irmã, chamada Maria, a qual, sentando-se também aos pés de Jesus, ouvia sua palavra."},"fr":{"prompt":"Chez Marthe, que faisait sa sœur Marie ?","bible_ref":"Luc 10:39","verse_text":"Elle avait une sœur, nommée Marie, qui, s’étant assise aux pieds du Seigneur, écoutait sa parole."},"en":{"prompt":"In Martha’s house, what did her sister Mary do?","bible_ref":"Luke 10:39","verse_text":"And she had a sister called Mary, which also sat at Jesus’ feet, and heard his word."},"es":{"prompt":"En casa de Marta, ¿qué hacía su hermana María?","bible_ref":"Lucas 10:39","verse_text":"Y ésta tenía una hermana que se llamaba María, la cual sentándose á los pies de Jesús, oía su palabra."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Sentava-se aos pés de Jesus e ouvia a sua palavra"},"fr":{"text":"Elle était assise aux pieds de Jésus et écoutait sa parole"},"en":{"text":"She sat at Jesus’ feet and heard his word"},"es":{"text":"Se sentaba a los pies de Jesús y oía su palabra"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Preparava a refeição"},"fr":{"text":"Elle préparait le repas"},"en":{"text":"She prepared the meal"},"es":{"text":"Preparaba la comida"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Tirava água do poço"},"fr":{"text":"Elle puisait de l’eau au puits"},"en":{"text":"She drew water at the well"},"es":{"text":"Sacaba agua del pozo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Lavava os pés dos discípulos"},"fr":{"text":"Elle lavait les pieds des disciples"},"en":{"text":"She washed the disciples’ feet"},"es":{"text":"Lavaba los pies de los discípulos"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-medium-012","type":"choice","level":"medium","testament":"nt","book":"LUK","chapter":12,"verse_start":18,"verse_end":18,"texts":{"pt":{"prompt":"Na parábola de Lucas 12, o que decidiu fazer o homem rico cuja terra dera muito fruto?","bible_ref":"Lucas 12:18","verse_text":"E disse: Farei isto: derrubarei meus celeiros, e construirei maiores, e ali juntarei toda esta minha colheita, e estes meus bens."},"fr":{"prompt":"Dans la parabole de Luc 12, que décida de faire l’homme riche dont les terres avaient beaucoup rapporté ?","bible_ref":"Luc 12:18","verse_text":"Voici, dit-il, ce que je ferai: j’abattrai mes greniers, j’en bâtirai de plus grands, j’y amasserai toute ma récolte et tous mes biens;"},"en":{"prompt":"In the parable of Luke 12, what did the rich man whose ground brought forth plentifully decide to do?","bible_ref":"Luke 12:18","verse_text":"And he said, This will I do: I will pull down my barns, and build greater; and there will I bestow all my fruits and my goods."},"es":{"prompt":"En la parábola de Lucas 12, ¿qué decidió hacer el hombre rico cuya heredad había dado mucho fruto?","bible_ref":"Lucas 12:18","verse_text":"Y dijo: Esto haré: derribaré mis alfolíes, y los edificaré mayores, y allí juntaré todos mis frutos y mis bienes;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Derrubar os celeiros e construir maiores"},"fr":{"text":"Abattre ses greniers et en bâtir de plus grands"},"en":{"text":"Pull down his barns and build greater"},"es":{"text":"Derribar sus alfolíes y edificarlos mayores"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Dar a colheita aos pobres"},"fr":{"text":"Donner sa récolte aux pauvres"},"en":{"text":"Give his fruits to the poor"},"es":{"text":"Dar sus frutos a los pobres"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Vender a sua terra"},"fr":{"text":"Vendre sa terre"},"en":{"text":"Sell his land"},"es":{"text":"Vender su heredad"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Oferecer tudo no templo"},"fr":{"text":"Tout offrir au temple"},"en":{"text":"Offer it all in the temple"},"es":{"text":"Ofrecerlo todo en el templo"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-medium-013","type":"choice","level":"medium","testament":"nt","book":"LUK","chapter":16,"verse_start":20,"verse_end":20,"texts":{"pt":{"prompt":"Na parábola do homem rico, como se chamava o mendigo deitado à sua porta?","bible_ref":"Lucas 16:20","verse_text":"Havia também um certo mendigo, de nome Lázaro, o qual ficava deitado à sua porta cheio de feridas."},"fr":{"prompt":"Dans la parabole de l’homme riche, comment s’appelait le pauvre couché à sa porte ?","bible_ref":"Luc 16:20","verse_text":"Un pauvre, nommé Lazare, était couché à sa porte, couvert d’ulcères,"},"en":{"prompt":"In the parable of the rich man, what was the name of the beggar laid at his gate?","bible_ref":"Luke 16:20","verse_text":"And there was a certain beggar named Lazarus, which was laid at his gate, full of sores,"},"es":{"prompt":"En la parábola del hombre rico, ¿cómo se llamaba el mendigo echado a su puerta?","bible_ref":"Lucas 16:20","verse_text":"Había también un mendigo llamado Lázaro, el cual estaba echado á la puerta de él, lleno de llagas,"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Lázaro"},"fr":{"text":"Lazare"},"en":{"text":"Lazarus"},"es":{"text":"Lázaro"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Bartimeu"},"fr":{"text":"Bartimée"},"en":{"text":"Bartimæus"},"es":{"text":"Bartimeo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Zaqueu"},"fr":{"text":"Zachée"},"en":{"text":"Zacchæus"},"es":{"text":"Zaqueo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Jairo"},"fr":{"text":"Jaïrus"},"en":{"text":"Jairus"},"es":{"text":"Jairo"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-medium-014","type":"choice","level":"medium","testament":"nt","book":"JHN","chapter":2,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Onde foi o casamento em que estava a mãe de Jesus?","bible_ref":"João 2:1","verse_text":"E no terceiro dia houve um casamento em Caná da Galileia; e a mãe de Jesus estava ali."},"fr":{"prompt":"Où eurent lieu les noces auxquelles se trouvait la mère de Jésus ?","bible_ref":"Jean 2:1","verse_text":"Trois jours après, il y eut des noces à Cana en Galilée. La mère de Jésus était là,"},"en":{"prompt":"Where was the marriage at which the mother of Jesus was?","bible_ref":"John 2:1","verse_text":"And the third day there was a marriage in Cana of Galilee; and the mother of Jesus was there:"},"es":{"prompt":"¿Dónde fueron las bodas en las que estaba la madre de Jesús?","bible_ref":"Juan 2:1","verse_text":"Y al tercer día hiciéronse unas bodas en Caná de Galilea; y estaba allí la madre de Jesús."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Em Caná da Galileia"},"fr":{"text":"À Cana en Galilée"},"en":{"text":"In Cana of Galilee"},"es":{"text":"En Caná de Galilea"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Em Betânia"},"fr":{"text":"À Béthanie"},"en":{"text":"In Bethany"},"es":{"text":"En Bethania"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Em Naim"},"fr":{"text":"À Naïn"},"en":{"text":"In Nain"},"es":{"text":"En Naín"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Em Cafarnaum"},"fr":{"text":"À Capernaüm"},"en":{"text":"In Capernaum"},"es":{"text":"En Capernaum"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-medium-015","type":"choice","level":"medium","testament":"nt","book":"JHN","chapter":21,"verse_start":17,"verse_end":17,"texts":{"pt":{"prompt":"Depois da ressurreição, quantas vezes perguntou Jesus a Simão Pedro se o amava?","bible_ref":"João 21:17","verse_text":"Disse-lhe a terceira vez: Simão, filho de Jonas, tu me amas? Entristeceu-se Pedro de que já pela terceira vez lhe dissesse: Tu me amas? E disse-lhe: Senhor, tu sabes todas as coisas, tu sabes que eu te amo. Disse-lhe Jesus: Alimenta minhas ovelhas."},"fr":{"prompt":"Après la résurrection, combien de fois Jésus demanda-t-il à Simon Pierre s’il l’aimait ?","bible_ref":"Jean 21:17","verse_text":"Il lui dit pour la troisième fois: Simon, fils de Jonas, m’aimes-tu? Pierre fut attristé de ce qu’il lui avait dit pour la troisième fois: M’aimes-tu? Et il lui répondit: Seigneur, tu sais toutes choses, tu sais que je t’aime. Jésus lui dit: Pais mes brebis."},"en":{"prompt":"After the resurrection, how many times did Jesus ask Simon Peter if he loved him?","bible_ref":"John 21:17","verse_text":"He saith unto him the third time, Simon, son of Jonas, lovest thou me? Peter was grieved because he said unto him the third time, Lovest thou me? And he said unto him, Lord, thou knowest all things; thou knowest that I love thee. Jesus saith unto him, Feed my sheep."},"es":{"prompt":"Después de la resurrección, ¿cuántas veces preguntó Jesús a Simón Pedro si le amaba?","bible_ref":"Juan 21:17","verse_text":"Dícele la tercera vez: Simón, hijo de Jonás, ¿me amas? Entristecióse Pedro de que le dijese la tercera vez: ¿Me amas? y dícele: Señor, tú sabes todas las cosas; tú sabes que te amo. Dícele Jesús: Apacienta mis ovejas."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Três vezes"},"fr":{"text":"Trois fois"},"en":{"text":"Three times"},"es":{"text":"Tres veces"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Uma vez"},"fr":{"text":"Une fois"},"en":{"text":"Once"},"es":{"text":"Una vez"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Duas vezes"},"fr":{"text":"Deux fois"},"en":{"text":"Twice"},"es":{"text":"Dos veces"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Sete vezes"},"fr":{"text":"Sept fois"},"en":{"text":"Seven times"},"es":{"text":"Siete veces"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-medium-016","type":"choice","level":"medium","testament":"nt","book":"JHN","chapter":19,"verse_start":19,"verse_end":19,"texts":{"pt":{"prompt":"O que estava escrito no título que Pilatos pôs sobre a cruz?","bible_ref":"João 19:19","verse_text":"E Pilatos também escreveu um título, e o pôs encima da cruz, e estava nele escrito: JESUS NAZARENO, REI DOS JUDEUS."},"fr":{"prompt":"Qu’était-il écrit sur l’inscription que Pilate plaça sur la croix ?","bible_ref":"Jean 19:19","verse_text":"Pilate fit une inscription, qu’il plaça sur la croix, et qui était ainsi conçue: Jésus de Nazareth, roi des Juifs."},"en":{"prompt":"What was written on the title Pilate put on the cross?","bible_ref":"John 19:19","verse_text":"And Pilate wrote a title, and put it on the cross. And the writing was, JESUS OF NAZARETH THE KING OF THE JEWS."},"es":{"prompt":"¿Qué estaba escrito en el título que Pilato puso encima de la cruz?","bible_ref":"Juan 19:19","verse_text":"Y escribió también Pilato un título, que puso encima de la cruz. Y el escrito era: JESUS NAZARENO, REY DE LOS JUDIOS."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Jesus Nazareno, Rei dos Judeus"},"fr":{"text":"Jésus de Nazareth, roi des Juifs"},"en":{"text":"Jesus of Nazareth the King of the Jews"},"es":{"text":"Jesús Nazareno, Rey de los Judíos"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Jesus, o Filho de Deus"},"fr":{"text":"Jésus, le Fils de Dieu"},"en":{"text":"Jesus, the Son of God"},"es":{"text":"Jesús, el Hijo de Dios"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Jesus, o Profeta da Galileia"},"fr":{"text":"Jésus, le prophète de Galilée"},"en":{"text":"Jesus, the Prophet of Galilee"},"es":{"text":"Jesús, el Profeta de Galilea"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Este é o Messias de Israel"},"fr":{"text":"Celui-ci est le Messie d’Israël"},"en":{"text":"This is the Messiah of Israel"},"es":{"text":"Éste es el Mesías de Israel"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-medium-017","type":"choice","level":"medium","testament":"nt","book":"JHN","chapter":4,"verse_start":18,"verse_end":18,"texts":{"pt":{"prompt":"Junto ao poço, quantos maridos disse Jesus que a mulher samaritana tinha tido?","bible_ref":"João 4:18","verse_text":"Porque cinco maridos tiveste, e o que agora tens não é teu marido; isto com verdade disseste."},"fr":{"prompt":"Près du puits, combien de maris Jésus dit-il que la Samaritaine avait eus ?","bible_ref":"Jean 4:18","verse_text":"Car tu as eu cinq maris, et celui que tu as maintenant n’est pas ton mari. En cela tu as dit vrai."},"en":{"prompt":"At the well, how many husbands did Jesus say the woman of Samaria had had?","bible_ref":"John 4:18","verse_text":"For thou hast had five husbands; and he whom thou now hast is not thy husband: in that saidst thou truly."},"es":{"prompt":"Junto al pozo, ¿cuántos maridos dijo Jesús que había tenido la samaritana?","bible_ref":"Juan 4:18","verse_text":"Porque cinco maridos has tenido: y el que ahora tienes no es tu marido; esto has dicho con verdad."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Cinco"},"fr":{"text":"Cinq"},"en":{"text":"Five"},"es":{"text":"Cinco"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Dois"},"fr":{"text":"Deux"},"en":{"text":"Two"},"es":{"text":"Dos"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Três"},"fr":{"text":"Trois"},"en":{"text":"Three"},"es":{"text":"Tres"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Sete"},"fr":{"text":"Sept"},"en":{"text":"Seven"},"es":{"text":"Siete"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-medium-018","type":"choice","level":"medium","testament":"nt","book":"JHN","chapter":12,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Depois de ungir os pés de Jesus com nardo, com que os enxugou Maria?","bible_ref":"João 12:3","verse_text":"Tomando então Maria um arrátel de óleo perfumado de nardo puro, de muito preço, ungiu os pés de Jesus, e limpou os pés dele com seus cabelos; e encheu-se a casa do cheiro do óleo perfumado."},"fr":{"prompt":"Après avoir oint les pieds de Jésus de nard, avec quoi Marie les essuya-t-elle ?","bible_ref":"Jean 12:3","verse_text":"Marie, ayant pris une livre d’un parfum de nard pur de grand prix, oignit les pieds de Jésus, et elle lui essuya les pieds avec ses cheveux; et la maison fut remplie de l’odeur du parfum."},"en":{"prompt":"After anointing Jesus’ feet with spikenard, with what did Mary wipe them?","bible_ref":"John 12:3","verse_text":"Then took Mary a pound of ointment of spikenard, very costly, and anointed the feet of Jesus, and wiped his feet with her hair: and the house was filled with the odour of the ointment."},"es":{"prompt":"Después de ungir los pies de Jesús con nardo, ¿con qué los limpió María?","bible_ref":"Juan 12:3","verse_text":"Entonces María tomó una libra de ungüento de nardo líquido de mucho precio, y ungió los pies de Jesús, y limpió sus pies con sus cabellos: y la casa se llenó del olor del ungüento."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Com os seus cabelos"},"fr":{"text":"Avec ses cheveux"},"en":{"text":"With her hair"},"es":{"text":"Con sus cabellos"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Com uma toalha"},"fr":{"text":"Avec un linge"},"en":{"text":"With a towel"},"es":{"text":"Con una toalla"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Com o seu manto"},"fr":{"text":"Avec son manteau"},"en":{"text":"With her mantle"},"es":{"text":"Con su manto"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Com folhas de palmeira"},"fr":{"text":"Avec des feuilles de palmier"},"en":{"text":"With palm leaves"},"es":{"text":"Con hojas de palmera"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-medium-019","type":"choice","level":"medium","testament":"nt","book":"ACT","chapter":18,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Em Atos 18:3, qual era o ofício de Paulo e daqueles com quem ele ficou a trabalhar?","bible_ref":"Atos 18:3","verse_text":"E porque era do mesmo ofício, ficou com eles, e trabalhava; porque tinham o ofício de fazerem tendas."},"fr":{"prompt":"En Actes 18:3, quel était le métier de Paul et de ceux chez qui il travailla ?","bible_ref":"Actes 18:3","verse_text":"et, comme il avait le même métier, il demeura chez eux et y travailla: ils étaient faiseurs de tentes."},"en":{"prompt":"In Acts 18:3, what was the craft of Paul and of those he abode and wrought with?","bible_ref":"Acts 18:3","verse_text":"And because he was of the same craft, he abode with them, and wrought: for by their occupation they were tentmakers."},"es":{"prompt":"En Hechos 18:3, ¿cuál era el oficio de Pablo y de aquellos con quienes trabajaba?","bible_ref":"Hechos 18:3","verse_text":"Y porque era de su oficio, posó con ellos, y trabajaba; porque el oficio de ellos era hacer tiendas."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Fabricantes de tendas"},"fr":{"text":"Faiseurs de tentes"},"en":{"text":"Tentmakers"},"es":{"text":"Fabricantes de tiendas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Pescadores"},"fr":{"text":"Pêcheurs"},"en":{"text":"Fishermen"},"es":{"text":"Pescadores"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Carpinteiros"},"fr":{"text":"Charpentiers"},"en":{"text":"Carpenters"},"es":{"text":"Carpinteros"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Oleiros"},"fr":{"text":"Potiers"},"en":{"text":"Potters"},"es":{"text":"Alfareros"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-medium-020","type":"choice","level":"medium","testament":"nt","book":"ACT","chapter":28,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Depois do naufrágio, como se chamava a ilha onde Paulo e os outros se salvaram?","bible_ref":"Atos 28:1","verse_text":"E tendo sobrevivido, então souberam que a ilha se chamava Malta."},"fr":{"prompt":"Après le naufrage, comment s’appelait l’île où Paul et les autres se sauvèrent ?","bible_ref":"Actes 28:1","verse_text":"Après nous être sauvés, nous reconnûmes que l’île s’appelait Malte."},"en":{"prompt":"After the shipwreck, what was the island called where Paul and the others escaped?","bible_ref":"Acts 28:1","verse_text":"And when they were escaped, then they knew that the island was called Melita."},"es":{"prompt":"Después del naufragio, ¿cómo se llamaba la isla donde Pablo y los demás escaparon?","bible_ref":"Hechos 28:1","verse_text":"Y cuando escapamos, entonces supimos que la isla se llamaba Melita."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Malta"},"fr":{"text":"Malte"},"en":{"text":"Melita"},"es":{"text":"Melita"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Chipre"},"fr":{"text":"Chypre"},"en":{"text":"Cyprus"},"es":{"text":"Cipro"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Creta"},"fr":{"text":"Crète"},"en":{"text":"Crete"},"es":{"text":"Creta"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Rodes"},"fr":{"text":"Rhodes"},"en":{"text":"Rhodes"},"es":{"text":"Rhodas"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-medium-021","type":"choice","level":"medium","testament":"nt","book":"ACT","chapter":3,"verse_start":2,"verse_end":2,"texts":{"pt":{"prompt":"Como se chamava a porta do templo onde punham todos os dias o coxo de nascença?","bible_ref":"Atos 3:2","verse_text":"E um certo homem estava sendo trazido, que era aleijado desde o ventre de sua mãe, ao qual todo dia colocavam à porta do Templo, chamada Porta Formosa, para pedir esmola aos que entravam no Templo."},"fr":{"prompt":"Comment s’appelait la porte du temple où l’on plaçait chaque jour le boiteux de naissance ?","bible_ref":"Actes 3:2","verse_text":"Il y avait un homme boiteux de naissance, qu’on portait et qu’on plaçait tous les jours à la porte du temple appelée la Belle, pour qu’il demandât l’aumône à ceux qui entraient dans le temple."},"en":{"prompt":"What was the name of the temple gate where the man lame from birth was laid daily?","bible_ref":"Acts 3:2","verse_text":"And a certain man lame from his mother’s womb was carried, whom they laid daily at the gate of the temple which is called Beautiful, to ask alms of them that entered into the temple;"},"es":{"prompt":"¿Cómo se llamaba la puerta del templo donde ponían cada día al cojo de nacimiento?","bible_ref":"Hechos 3:2","verse_text":"Y un hombre que era cojo desde el vientre de su madre, era traído; al cual ponían cada día á la puerta del templo que se llama la Hermosa, para que pidiese limosna de los que entraban en el templo."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Formosa"},"fr":{"text":"La Belle"},"en":{"text":"Beautiful"},"es":{"text":"La Hermosa"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Dourada"},"fr":{"text":"La Dorée"},"en":{"text":"Golden"},"es":{"text":"La Dorada"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Real"},"fr":{"text":"La Royale"},"en":{"text":"Royal"},"es":{"text":"La Real"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Das Ovelhas"},"fr":{"text":"Des Brebis"},"en":{"text":"Sheep"},"es":{"text":"De las Ovejas"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-medium-022","type":"order","level":"medium","testament":"nt","book":"MAT","chapter":16,"verse_start":16,"verse_end":16,"texts":{"pt":{"prompt":"Ordena estes episódios de Mateus pela ordem em que aconteceram.","bible_ref":"Mateus 16:16","verse_text":null},"fr":{"prompt":"Mets ces épisodes de Matthieu dans l’ordre où ils se sont produits.","bible_ref":"Matthieu 16:16","verse_text":null},"en":{"prompt":"Put these episodes from Matthew in the order they happened.","bible_ref":"Matthew 16:16","verse_text":null},"es":{"prompt":"Ordena estos episodios de Mateo según ocurrieron.","bible_ref":"Mateo 16:16","verse_text":null}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"Simão Pedro diz: «Tu és o Cristo»","ref":"Mateus 16:16"},"fr":{"text":"Simon Pierre dit : « Tu es le Christ »","ref":"Matthieu 16:16"},"en":{"text":"Simon Peter says, “Thou art the Christ”","ref":"Matthew 16:16"},"es":{"text":"Simón Pedro dice: «Tú eres el Cristo»","ref":"Mateo 16:16"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Jesus é transfigurado: o seu rosto brilha como o sol","ref":"Mateus 17:2"},"fr":{"text":"Jésus est transfiguré : son visage resplendit comme le soleil","ref":"Matthieu 17:2"},"en":{"text":"Jesus is transfigured: his face shines as the sun","ref":"Matthew 17:2"},"es":{"text":"Jesús se transfigura: su rostro resplandece como el sol","ref":"Mateo 17:2"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Jesus repreende o demónio e o menino fica são","ref":"Mateus 17:18"},"fr":{"text":"Jésus menace le démon et l’enfant est guéri","ref":"Matthieu 17:18"},"en":{"text":"Jesus rebukes the devil and the child is cured","ref":"Matthew 17:18"},"es":{"text":"Jesús reprende al demonio y el mozo queda sano","ref":"Mateo 17:18"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Pedro deve achar uma moeda na boca de um peixe","ref":"Mateus 17:27"},"fr":{"text":"Pierre doit trouver une pièce dans l