select public.upsert_bank_question($json${"id":"evan2-medium-023","type":"order","level":"medium","testament":"nt","book":"MAT","chapter":27,"verse_start":26,"verse_end":26,"texts":{"pt":{"prompt":"Ordena estes episódios de Mateus pela ordem em que aconteceram.","bible_ref":"Mateus 27:26","verse_text":null},"fr":{"prompt":"Mets ces épisodes de Matthieu dans l’ordre où ils se sont produits.","bible_ref":"Matthieu 27:26","verse_text":null},"en":{"prompt":"Put these episodes from Matthew in the order they happened.","bible_ref":"Matthew 27:26","verse_text":null},"es":{"prompt":"Ordena estos episodios de Mateo según ocurrieron.","bible_ref":"Mateo 27:26","verse_text":null}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"Pilatos solta Barrabás","ref":"Mateus 27:26"},"fr":{"text":"Pilate relâche Barabbas","ref":"Matthieu 27:26"},"en":{"text":"Pilate releases Barabbas","ref":"Matthew 27:26"},"es":{"text":"Pilato suelta a Barrabás","ref":"Mateo 27:26"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Dois homens são crucificados com Jesus","ref":"Mateus 27:38"},"fr":{"text":"Deux brigands sont crucifiés avec Jésus","ref":"Matthieu 27:38"},"en":{"text":"Two thieves are crucified with Jesus","ref":"Matthew 27:38"},"es":{"text":"Dos ladrones son crucificados con Jesús","ref":"Mateo 27:38"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"O véu do templo rasga-se em dois","ref":"Mateus 27:51"},"fr":{"text":"Le voile du temple se déchire en deux","ref":"Matthieu 27:51"},"en":{"text":"The veil of the temple is rent in twain","ref":"Matthew 27:51"},"es":{"text":"El velo del templo se rompe en dos","ref":"Mateo 27:51"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"A pedra do sepulcro é selada e guardada","ref":"Mateus 27:66"},"fr":{"text":"La pierre du sépulcre est scellée et gardée","ref":"Matthieu 27:66"},"en":{"text":"The stone is sealed and a watch set","ref":"Matthew 27:66"},"es":{"text":"Sellan la piedra del sepulcro con la guardia","ref":"Mateo 27:66"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-medium-024","type":"order","level":"medium","testament":"nt","book":"MRK","chapter":1,"verse_start":30,"verse_end":31,"texts":{"pt":{"prompt":"Ordena estes episódios de Marcos pela ordem em que aconteceram.","bible_ref":"Marcos 1:30-31","verse_text":null},"fr":{"prompt":"Mets ces épisodes de Marc dans l’ordre où ils se sont produits.","bible_ref":"Marc 1:30-31","verse_text":null},"en":{"prompt":"Put these episodes from Mark in the order they happened.","bible_ref":"Mark 1:30-31","verse_text":null},"es":{"prompt":"Ordena estos episodios de Marcos según ocurrieron.","bible_ref":"Marcos 1:30-31","verse_text":null}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"Jesus cura da febre a sogra de Simão","ref":"Marcos 1:30-31"},"fr":{"text":"Jésus guérit de la fièvre la belle-mère de Simon","ref":"Marc 1:30-31"},"en":{"text":"Jesus heals Simon’s wife’s mother of a fever","ref":"Mark 1:30-31"},"es":{"text":"Jesús sana de la calentura a la suegra de Simón","ref":"Marcos 1:30-31"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Jesus diz a um paralítico: «Toma o teu leito»","ref":"Marcos 2:11"},"fr":{"text":"Jésus dit à un paralytique : « Prends ton lit »","ref":"Marc 2:11"},"en":{"text":"Jesus tells one sick of the palsy, “Take up thy bed”","ref":"Mark 2:11"},"es":{"text":"Jesús dice a un paralítico: «Toma tu lecho»","ref":"Marcos 2:11"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Jesus chama Levi, que estava no posto de impostos","ref":"Marcos 2:14"},"fr":{"text":"Jésus appelle Lévi, assis au bureau des péages","ref":"Marc 2:14"},"en":{"text":"Jesus calls Levi, sitting at the receipt of custom","ref":"Mark 2:14"},"es":{"text":"Jesús llama a Leví, sentado al banco de los tributos","ref":"Marcos 2:14"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Jesus cura um homem que tinha a mão definhada","ref":"Marcos 3:5"},"fr":{"text":"Jésus guérit un homme qui avait la main sèc