select public.upsert_bank_question($json${"id":"evan2-medium-035","type":"verse","level":"medium","testament":"nt","book":"ACT","chapter":1,"verse_start":8,"verse_end":8,"texts":{"pt":{"prompt":"Mas vós recebereis _____ do Espírito Santo, que virá sobre vós; e vós sereis minhas testemunhas, tanto em Jerusalém como em toda a Judeia, e Samaria, e até ao último lugar da terra.","bible_ref":"Atos 1:8","verse_text":"Mas vós recebereis poder do Espírito Santo, que virá sobre vós; e vós sereis minhas testemunhas, tanto em Jerusalém como em toda a Judeia, e Samaria, e até ao último lugar da terra."},"fr":{"prompt":"Mais vous recevrez une _____, le Saint-Esprit survenant sur vous, et vous serez mes témoins à Jérusalem, dans toute la Judée, dans la Samarie, et jusqu’aux extrémités de la terre.","bible_ref":"Actes 1:8","verse_text":"Mais vous recevrez une puissance, le Saint-Esprit survenant sur vous, et vous serez mes témoins à Jérusalem, dans toute la Judée, dans la Samarie, et jusqu’aux extrémités de la terre."},"en":{"prompt":"But ye shall receive _____, after that the Holy Ghost is come upon you: and ye shall be witnesses unto me both in Jerusalem, and in all Judæa, and in Samaria, and unto the uttermost part of the earth.","bible_ref":"Acts 1:8","verse_text":"But ye shall receive power, after that the Holy Ghost is come upon you: and ye shall be witnesses unto me both in Jerusalem, and in all Judæa, and in Samaria, and unto the uttermost part of the earth."},"es":{"prompt":"Mas recibiréis la _____ del Espíritu Santo que vendrá sobre vosotros; y me sereís testigos en Jerusalem, y en toda Judea, y Samaria, y hasta lo último de la tierra.","bible_ref":"Hechos 1:8","verse_text":"Mas recibiréis la virtud del Espíritu Santo que vendrá sobre vosotros; y me sereís testigos en Jerusalem, y en toda Judea, y Samaria, y hasta lo último de la tierra."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"poder"},"fr":{"text":"puissance"},"en":{"text":"power"},"es":{"tex