select public.upsert_bank_question($json${"id":"evan2-hard-001","type":"choice","level":"hard","testament":"nt","book":"MAT","chapter":27,"verse_start":19,"verse_end":19,"texts":{"pt":{"prompt":"Quem mandou dizer a Pilatos: «Nada faças com aquele justo», por ter sofrido em sonhos?","bible_ref":"Mateus 27:19","verse_text":"E, enquanto ele estava sentado no assento de juiz, sua mulher lhe enviou a seguinte mensagem: Nada faças com aquele justo, pois hoje sofri muito em sonhos por causa dele."},"fr":{"prompt":"Qui fit dire à Pilate : « Qu’il n’y ait rien entre toi et ce juste », après avoir souffert en songe ?","bible_ref":"Matthieu 27:19","verse_text":"Pendant qu’il était assis sur le tribunal, sa femme lui fit dire: Qu’il n’y ait rien entre toi et ce juste; car aujourd’hui j’ai beaucoup souffert en songe à cause de lui."},"en":{"prompt":"Who sent unto Pilate, saying, “Have thou nothing to do with that just man”, after suffering in a dream?","bible_ref":"Matthew 27:19","verse_text":"When he was set down on the judgment seat, his wife sent unto him, saying, Have thou nothing to do with that just man: for I have suffered many things this day in a dream because of him."},"es":{"prompt":"¿Quién envió a decir a Pilato: «No tengas que ver con aquel justo», por haber padecido en sueños?","bible_ref":"Mateo 27:19","verse_text":"Y estando él sentado en el tribunal, su mujer envió á él, diciendo: No tengas que ver con aquel justo; porque hoy he padecido muchas cosas en sueños por causa de él."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"A sua mulher"},"fr":{"text":"Sa femme"},"en":{"text":"His wife"},"es":{"text":"Su mujer"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Herodes"},"fr":{"text":"Hérode"},"en":{"text":"Herod"},"es":{"text":"Herodes"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Caifás"},"fr":{"text":"Caïphe"},"en":{"text":"Caiaphas"},"es":{"text":"Caifás"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"O 