select public.upsert_bank_question($json${"id":"evan2-hard-002","type":"choice","level":"hard","testament":"nt","book":"MAT","chapter":27,"verse_start":7,"verse_end":7,"texts":{"pt":{"prompt":"O que compraram os principais sacerdotes com as moedas de prata que Judas devolveu?","bible_ref":"Mateus 27:7","verse_text":"Então juntamente se aconselharam, e compraram com elas o campo do oleiro, para ser cemitério dos estrangeiros."},"fr":{"prompt":"Qu’achetèrent les principaux sacrificateurs avec l’argent que Judas avait rapporté ?","bible_ref":"Matthieu 27:7","verse_text":"Et, après en avoir délibéré, ils achetèrent avec cet argent le champ du potier, pour la sépulture des étrangers."},"en":{"prompt":"What did the chief priests buy with the silver Judas brought back?","bible_ref":"Matthew 27:7","verse_text":"And they took counsel, and bought with them the potter’s field, to bury strangers in."},"es":{"prompt":"¿Qué compraron los príncipes de los sacerdotes con las piezas de plata que devolvió Judas?","bible_ref":"Mateo 27:7","verse_text":"Mas habido consejo, compraron con ellas el campo del alfarero, por sepultura para los extranjeros."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O campo do oleiro"},"fr":{"text":"Le champ du potier"},"en":{"text":"The potter’s field"},"es":{"text":"El campo del alfarero"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um cordeiro para a Páscoa"},"fr":{"text":"Un agneau pour la Pâque"},"en":{"text":"A lamb for the passover"},"es":{"text":"Un cordero para la pascua"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Uma casa em Betânia"},"fr":{"text":"Une maison à Béthanie"},"en":{"text":"A house in Bethany"},"es":{"text":"Una casa en Bethania"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Óleo para o templo"},"fr":{"text":"De l’huile pour le temple"},"en":{"text":"Oil for the temple"},"es":{"text":"Aceite para el templo"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-hard-003","type":"choice","level":"hard","testament":"nt","book":"MAT","chapter":2,"verse_start":16,"verse_end":16,"texts":{"pt":{"prompt":"Herodes mandou matar os meninos de Belém de que idade para baixo?","bible_ref":"Mateus 2:16","verse_text":"Então Herodes, ao ver que tinha sido enganado pelos magos, irou-se muito, e mandou matar todos os meninos em Belém e em todos os limites de sua região, da idade de dois anos e abaixo, conforme o tempo que tinha perguntado com precisão dos magos."},"fr":{"prompt":"Hérode fit tuer les enfants de Bethléhem à partir de quel âge et au-dessous ?","bible_ref":"Matthieu 2:16","verse_text":"Alors Hérode, voyant qu’il avait été joué par les mages, se mit dans une grande colère, et il envoya tuer tous les enfants de deux ans et au-dessous qui étaient à Bethléhem et dans tout son territoire, selon la date dont il s’était soigneusement enquis auprès des mages."},"en":{"prompt":"Herod slew the children of Bethlehem from what age and under?","bible_ref":"Matthew 2:16","verse_text":"Then Herod, when he saw that he was mocked of the wise men, was exceeding wroth, and sent forth, and slew all the children that were in Bethlehem, and in all the coasts thereof, from two years old and under, according to the time which he had diligently enquired of the wise men."},"es":{"prompt":"¿De qué edad abajo mató Herodes a los niños de Bethlehem?","bible_ref":"Mateo 2:16","verse_text":"Herodes entonces, como se vió burlado de los magos, se enojó mucho, y envió, y mató á todos los niños que había en Bethlehem y en todos sus términos, de edad de dos años abajo, conforme al tiempo que había entendido de los magos."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Dois anos"},"fr":{"text":"Deux ans"},"en":{"text":"Two years old"},"es":{"text":"Dos años"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um ano"},"fr":{"text":"Un an"},"en":{"text":"One year old"},"es":{"text":"Un año"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Três anos"},"fr":{"text":"Trois ans"},"en":{"text":"Three years old"},"es":{"text":"Tres años"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Sete anos"},"fr":{"text":"Sept ans"},"en":{"text":"Seven years old"},"es":{"text":"Siete años"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-hard-004","type":"choice","level":"hard","testament":"nt","book":"MAT","chapter":20,"verse_start":2,"verse_end":2,"texts":{"pt":{"prompt":"Na parábola dos trabalhadores da vinha, por quanto ao dia se acertou o dono com os primeiros?","bible_ref":"Mateus 20:2","verse_text":"Ele entrou em acordo com os trabalhadores por um denário ao dia, e os mandou à sua vinha."},"fr":{"prompt":"Dans la parabole des ouvriers de la vigne, pour combien par jour le maître convint-il avec les premiers ?","bible_ref":"Matthieu 20:2","verse_text":"Il convint avec eux d’un denier par jour, et il les envoya à sa vigne."},"en":{"prompt":"In the parable of the labourers in the vineyard, for how much a day did the householder agree with the first?","bible_ref":"Matthew 20:2","verse_text":"And when he had agreed with the labourers for a penny a day, he sent them into his vineyard."},"es":{"prompt":"En la parábola de los obreros de la viña, ¿en cuánto al día se concertó el padre de familia con los primeros?","bible_ref":"Mateo 20:2","verse_text":"Y habiéndose concertado con los obreros en un denario al día, los envió á su viña."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Um denário"},"fr":{"text":"Un denier"},"en":{"text":"A penny"},"es":{"text":"Un denario"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um talento"},"fr":{"text":"Un talent"},"en":{"text":"A talent"},"es":{"text":"Un talento"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Uma mina"},"fr":{"text":"Une mine"},"en":{"text":"A pound"},"es":{"text":"Una mina"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Trinta moedas de prata"},"fr":{"text":"Trente pièces d’argent"},"en":{"text":"Thirty pieces of silver"},"es":{"text":"Treinta piezas de plata"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-hard-005","type":"choice","level":"hard","testament":"nt","book":"MAT","chapter":26,"verse_start":6,"verse_end":7,"texts":{"pt":{"prompt":"Em Betânia, em casa de quem estava Jesus quando uma mulher lhe derramou perfume na cabeça?","bible_ref":"Mateus 26:6-7","verse_text":"Enquanto Jesus estava em Betânia, na casa de Simão o leproso, veio a ele uma mulher com um vaso de alabastro, de óleo perfumado de grande valor, e derramou sobre a cabeça dele, enquanto estava sentado à mesa."},"fr":{"prompt":"À Béthanie, dans la maison de qui était Jésus quand une femme répandit un parfum sur sa tête ?","bible_ref":"Matthieu 26:6-7","verse_text":"Comme Jésus était à Béthanie, dans la maison de Simon le lépreux, une femme s’approcha de lui, tenant un vase d’albâtre, qui renfermait un parfum de grand prix; et, pendant qu’il était à table, elle répandit le parfum sur sa tête."},"en":{"prompt":"In Bethany, in whose house was Jesus when a woman poured ointment on his head?","bible_ref":"Matthew 26:6-7","verse_text":"Now when Jesus was in Bethany, in the house of Simon the leper, There came unto him a woman having an alabaster box of very precious ointment, and poured it on his head, as he sat at meat."},"es":{"prompt":"En Bethania, ¿en casa de quién estaba Jesús cuando una mujer derramó ungüento sobre su cabeza?","bible_ref":"Mateo 26:6-7","verse_text":"Y estando Jesús en Bethania, en casa de Simón el leproso, Vino á él una mujer, teniendo un vaso de alabastro de ungüento de gran precio, y lo derramó sobre la cabeza de él, estando sentado á la mesa."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Simão, o leproso"},"fr":{"text":"Simon le lépreux"},"en":{"text":"Simon the leper"},"es":{"text":"Simón el leproso"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Zaqueu"},"fr":{"text":"Zachée"},"en":{"text":"Zacchæus"},"es":{"text":"Zaqueo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Nicodemos"},"fr":{"text":"Nicodème"},"en":{"text":"Nicodemus"},"es":{"text":"Nicodemo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Jairo"},"fr":{"text":"Jaïrus"},"en":{"text":"Jairus"},"es":{"text":"Jairo"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-hard-006","type":"choice","level":"hard","testament":"nt","book":"MRK","chapter":3,"verse_start":17,"verse_end":17,"texts":{"pt":{"prompt":"Que nome deu Jesus a Tiago e João, filhos de Zebedeu?","bible_ref":"Marcos 3:17","verse_text":"Tiago filho de Zebedeu, e João, irmão de Tiago; e pôs-lhes por nome Boanerges, que significa “filhos do trovão”;"},"fr":{"prompt":"Quel nom Jésus donna-t-il à Jacques et Jean, fils de Zébédée ?","bible_ref":"Marc 3:17","verse_text":"Jacques, fils de Zébédée, et Jean, frère de Jacques, auxquels il donna le nom de Boanergès, qui signifie fils du tonnerre;"},"en":{"prompt":"What name did Jesus give James and John, the sons of Zebedee?","bible_ref":"Mark 3:17","verse_text":"And James the son of Zebedee, and John the brother of James; and he surnamed them Boanerges, which is, The sons of thunder:"},"es":{"prompt":"¿Qué nombre puso Jesús a Jacobo y Juan, hijos de Zebedeo?","bible_ref":"Marcos 3:17","verse_text":"Y á Jacobo, hijo de Zebedeo, y á Juan hermano de Jacobo; y les apellidó Boanerges, que es, Hijos del trueno;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Boanerges"},"fr":{"text":"Boanergès"},"en":{"text":"Boanerges"},"es":{"text":"Boanerges"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Cefas"},"fr":{"text":"Céphas"},"en":{"text":"Cephas"},"es":{"text":"Cephas"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Dídimo"},"fr":{"text":"Didyme"},"en":{"text":"Didymus"},"es":{"text":"Dídimo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Barnabé"},"fr":{"text":"Barnabas"},"en":{"text":"Barnabas"},"es":{"text":"Bernabé"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-hard-007","type":"choice","level":"hard","testament":"nt","book":"MRK","chapter":5,"verse_start":13,"verse_end":13,"texts":{"pt":{"prompt":"Segundo Marcos, quantos porcos havia na manada que se precipitou no mar?","bible_ref":"Marcos 5:13","verse_text":"Imediatamente Jesus lhes permitiu. Então aqueles espíritos imundos saíram para entrar nos porcos; e a manada lançou-se abaixo no mar; (eram quase dois mil) e afogaram-se no mar."},"fr":{"prompt":"Selon Marc, combien de pourceaux y avait-il dans le troupeau qui se précipita dans la mer ?","bible_ref":"Marc 5:13","verse_text":"Il le leur permit. Et les esprits impurs sortirent, entrèrent dans les pourceaux, et le troupeau se précipita des pentes escarpées dans la mer: il y en avait environ deux mille, et ils se noyèrent dans la mer."},"en":{"prompt":"According to Mark, about how many swine were in the herd that ran down into the sea?","bible_ref":"Mark 5:13","verse_text":"And forthwith Jesus gave them leave. And the unclean spirits went out, and entered into the swine: and the herd ran violently down a steep place into the sea, (they were about two thousand;) and were choked in the sea."},"es":{"prompt":"Según Marcos, ¿cuántos puercos había en la manada que cayó en la mar?","bible_ref":"Marcos 5:13","verse_text":"Y luego Jesús se lo permitió. Y saliendo aquellos espíritus inmundos, entraron en los puercos, y la manada cayó por un despeñadero en la mar; los cuales eran como dos mil; y en la mar se ahogaron."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Cerca de dois mil"},"fr":{"text":"Environ deux mille"},"en":{"text":"About two thousand"},"es":{"text":"Como dos mil"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Cerca de duzentos"},"fr":{"text":"Environ deux cents"},"en":{"text":"About two hundred"},"es":{"text":"Como doscientos"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Cerca de quinhentos"},"fr":{"text":"Environ cinq cents"},"en":{"text":"About five hundred"},"es":{"text":"Como quinientos"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Cerca de cinco mil"},"fr":{"text":"Environ cinq mille"},"en":{"text":"About five thousand"},"es":{"text":"Como cinco mil"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-hard-008","type":"choice","level":"hard","testament":"nt","book":"MRK","chapter":1,"verse_start":13,"verse_end":13,"texts":{"pt":{"prompt":"Segundo Marcos 1:13, com quem estava Jesus no deserto, enquanto os anjos o serviam?","bible_ref":"Marcos 1:13","verse_text":"Ele esteve ali no deserto quarenta dias, tentado por Satanás. Ele estava com os animais selvagens, e os anjos o serviam."},"fr":{"prompt":"Selon Marc 1:13, avec qui Jésus était-il au désert, pendant que les anges le servaient ?","bible_ref":"Marc 1:13","verse_text":"où il passa quarante jours, tenté par Satan. Il était avec les bêtes sauvages, et les anges le servaient."},"en":{"prompt":"According to Mark 1:13, who was Jesus with in the wilderness, while the angels ministered unto him?","bible_ref":"Mark 1:13","verse_text":"And he was there in the wilderness forty days, tempted of Satan; and was with the wild beasts; and the angels ministered unto him."},"es":{"prompt":"Según Marcos 1:13, ¿con quién estaba Jesús en el desierto, mientras los ángeles le servían?","bible_ref":"Marcos 1:13","verse_text":"Y estuvo allí en el desierto cuarenta días, y era tentado de Satanás; y estaba con las fieras; y los ángeles le servían."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Com os animais selvagens"},"fr":{"text":"Avec les bêtes sauvages"},"en":{"text":"With the wild beasts"},"es":{"text":"Con las fieras"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Com os seus discípulos"},"fr":{"text":"Avec ses disciples"},"en":{"text":"With his disciples"},"es":{"text":"Con sus discípulos"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Com João Batista"},"fr":{"text":"Avec Jean-Baptiste"},"en":{"text":"With John the Baptist"},"es":{"text":"Con Juan el Bautista"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Com uns pastores"},"fr":{"text":"Avec des bergers"},"en":{"text":"With some shepherds"},"es":{"text":"Con unos 