select public.upsert_bank_question($json${"id":"evan2-hard-009","type":"choice","level":"hard","testament":"nt","book":"MRK","chapter":16,"verse_start":9,"verse_end":9,"texts":{"pt":{"prompt":"Quantos demónios tinha Jesus expulsado de Maria Madalena?","bible_ref":"Marcos 16:9","verse_text":"E havendo ressuscitado pela manhã, no primeiro dia da semana, Jesus apareceu primeiramente a Maria Madalena, da qual havia expulsado sete demônios."},"fr":{"prompt":"Combien de démons Jésus avait-il chassés de Marie de Magdala ?","bible_ref":"Marc 16:9","verse_text":"Jésus, étant ressuscité le matin du premier jour de la semaine, apparut d’abord à Marie de Magdala, de laquelle il avait chassé sept démons."},"en":{"prompt":"How many devils had Jesus cast out of Mary Magdalene?","bible_ref":"Mark 16:9","verse_text":"Now when Jesus was risen early the first day of the week, he appeared first to Mary Magdalene, out of whom he had cast seven devils."},"es":{"prompt":"¿Cuántos demonios había echado Jesús de María Magdalena?","bible_ref":"Marcos 16:9","verse_text":"Mas como Jesús resucitó por la mañana, el primer día de la semana, apareció primeramente á María Magdalena, de la cual había echado siete demonios."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Sete"},"fr":{"text":"Sept"},"en":{"text":"Seven"},"es":{"text":"Siete"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Três"},"fr":{"text":"Trois"},"en":{"text":"Three"},"es":{"text":"Tres"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Cinco"},"fr":{"text":"Cinq"},"en":{"text":"Five"},"es":{"text":"Cinco"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Doze"},"fr":{"text":"Douze"},"en":{"text":"Twelve"},"es":{"text":"Doce"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-hard-010","type":"choice","level":"hard","testament":"nt","book":"LUK","chapter":8,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Joana, uma das mulheres que serviam Jesus, era mulher de Cuza. De quem era Cuza mordomo?","bible_ref":"Lucas 8:3","verse_text":"e Joana, a mulher de Cuza, mordomo de Herodes; e Susana, e muitas outras, que o serviam com seus bens."},"fr":{"prompt":"Jeanne, une des femmes qui assistaient Jésus, était femme de Chuza. De qui Chuza était-il l’intendant ?","bible_ref":"Luc 8:3","verse_text":"Jeanne, femme de Chuza, intendant d’Hérode, Susanne, et plusieurs autres, qui l’assistaient de leurs biens."},"en":{"prompt":"Joanna, one of the women who ministered unto Jesus, was the wife of Chuza. Whose steward was Chuza?","bible_ref":"Luke 8:3","verse_text":"And Joanna the wife of Chuza Herod’s steward, and Susanna, and many others, which ministered unto him of their substance."},"es":{"prompt":"Juana, una de las mujeres que servían a Jesús, era mujer de Chuza. ¿De quién era Chuza procurador?","bible_ref":"Lucas 8:3","verse_text":"Y Juana, mujer de Chuza, procurador de Herodes, y Susana, y otras muchas que le servían de sus haciendas."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"De Herodes"},"fr":{"text":"D’Hérode"},"en":{"text":"Herod’s"},"es":{"text":"De Herodes"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"De Pilatos"},"fr":{"text":"De Pilate"},"en":{"text":"Pilate’s"},"es":{"text":"De Pilato"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"De Caifás"},"fr":{"text":"De Caïphe"},"en":{"text":"Caiaphas’"},"es":{"text":"De Caifás"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"De César"},"fr":{"text":"De César"},"en":{"text":"Cæsar’s"},"es":{"text":"De César"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-hard-011","type":"choice","level":"hard","testament":"nt","book":"LUK","chapter":24,"verse_start":13,"verse_end":13,"texts":{"pt":{"prompt":"Segundo Lucas 24:13, a que distância de Jerusalém ficava a aldeia de Emaús?","bible_ref":"Lucas 24:13","verse_text":"E eis que dois deles iam naquele mesmo dia a uma aldeia, cujo nome era Emaús, que estava a sessenta estádios de distância de Jerusalém."},"fr":{"prompt":"Selon Luc 24:13, à quelle distance de Jérusalem se trouvait le village d’Émmaüs ?","bible_ref":"Luc 24:13","verse_text":"Et voici, ce même jour, deux disciples allaient à un village nommé Émmaüs, éloigné de Jérusalem de soixante stades;"},"en":{"prompt":"According to Luke 24:13, how far from Jerusalem was the village of Emmaus?","bible_ref":"Luke 24:13","verse_text":"And, behold, two of them went that same day to a village called Emmaus, which was from Jerusalem about threescore furlongs."},"es":{"prompt":"Según Lucas 24:13, ¿a qué distancia de Jerusalem estaba la aldea de Emmaús?","bible_ref":"Lucas 24:13","verse_text":"Y he aquí, dos de ellos iban el mismo día á una aldea que estaba de Jerusalem sesenta estadios, llamada Emmaús."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Sessenta estádios"},"fr":{"text":"Soixante stades"},"en":{"text":"Threescore furlongs"},"es":{"text":"Sesenta estadios"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Trinta estádios"},"fr":{"text":"Trente stades"},"en":{"text":"Thirty furlongs"},"es":{"text":"Treinta estadios"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Cem estádios"},"fr":{"text":"Cent stades"},"en":{"text":"An hundred furlongs"},"es":{"text":"Cien estadios"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Vinte estádios"},"fr":{"text":"Vingt stades"},"en":{"text":"Twenty furlongs"},"es":{"text":"Veinte estadios"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-hard-012","type":"choice","level":"hard","testament":"nt","book":"LUK","chapter":13,"verse_start":4,"verse_end":4,"texts":{"pt":{"prompt":"Quantas pessoas morreram quando caiu a torre de Siloé?","bible_ref":"Lucas 13:4","verse_text":"Ou aqueles dezoito, sobre os quais a torre em Siloé caiu, matando-os; pensais que eram mais culpados dos que todos as pessoas que moravam em Jerusalém?"},"fr":{"prompt":"Combien de personnes moururent quand la tour de Siloé tomba ?","bible_ref":"Luc 13:4","verse_text":"Ou bien, ces dix-huit personnes sur qui est tombée la tour de Siloé et qu’elle a tuées, croyez-vous qu’elles fussent plus coupables que tous les autres habitants de Jérusalem?"},"en":{"prompt":"How many died when the tower in Siloam fell upon them?","bible_ref":"Luke 13:4","verse_text":"Or those eighteen, upon whom the tower in Siloam fell, and slew them, think ye that they were sinners above all men that dwelt in Jerusalem?"},"es":{"prompt":"¿Cuántos murieron cuando cayó la torre en Siloé?","bible_ref":"Lucas 13:4","verse_text":"O aquellos dieciocho, sobre los cuales cayó la torre en Siloé, y los mató, ¿pensáis que ellos fueron más deudores que todos los hombres que habitan en Jerusalem?"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Dezoito"},"fr":{"text":"Dix-huit"},"en":{"text":"Eighteen"},"es":{"text":"Dieciocho"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Doze"},"fr":{"text":"Douze"},"en":{"text":"Twelve"},"es":{"text":"Doce"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Quarenta"},"fr":{"text":"Quarante"},"en":{"text":"Forty"},"es":{"text":"Cuarenta"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Setenta"},"fr":{"text":"Septante"},"en":{"text":"Seventy"},"es":{"text":"Setenta"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-hard-013","type":"choice","level":"hard","testament":"nt","book":"LUK","chapter":1,"verse_start":5,"verse_end":5,"texts":{"pt":{"prompt":"Isabel, mulher do sacerdote Zacarias, era das filhas de quem?","bible_ref":"Lucas 1:5","verse_text":"Houve nos dias de Herodes, rei da Judeia, um sacerdote chamado Zacarias, da ordem de Abias; sua mulher das filhas de Arão, e o seu nome era Isabel."},"fr":{"prompt":"Élisabeth, femme du sacrificateur Zacharie, était d’entre les filles de qui ?","bible_ref":"Luc 1:5","verse_text":"Du temps d’Hérode, roi de Judée, il y avait un sacrificateur, nommé Zacharie, de la classe d’Abia; sa femme était d’entre les filles d’Aaron, et s’appelait Élisabeth."},"en":{"prompt":"Elisabeth, the wife of the priest Zacharias, was of the daughters of whom?","bible_ref":"Luke 1:5","verse_text":"There was in the days of Herod, the king of Judæa, a certain priest named Zacharias, of the course of Abia: and his wife was of the daughters of Aaron, and her name was Elisabeth."},"es":{"prompt":"Elisabet, mujer del sacerdote Zacarías, ¿de las hijas de quién era?","bible_ref":"Lucas 1:5","verse_text":"Hubo en los días de Herodes, rey de Judea, un sacerdote llamado Zacarías, de la suerte de Abías; y su mujer, de las hijas de Aarón, llamada Elisabet."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"De Arão"},"fr":{"text":"D’Aaron"},"en":{"text":"Of Aaron"},"es":{"text":"De Aarón"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"De David"},"fr":{"text":"De David"},"en":{"text":"Of David"},"es":{"text":"De David"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"De Moisés"},"fr":{"text":"De Moïse"},"en":{"text":"Of Moses"},"es":{"text":"De Moisés"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"De Jacob"},"fr":{"text":"De Jacob"},"en":{"text":"Of Jacob"},"es":{"text":"De Jacob"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-hard-014","type":"choice","level":"hard","testament":"nt","book":"LUK","chapter":19,"verse_start":13,"verse_end":13,"texts":{"pt":{"prompt":"Na parábola das minas, quantos servos chamou o homem nobre antes de partir?","bible_ref":"Lucas 19:13","verse_text":"E chamando dez servos seus, deu-lhes dez minas, e disse-lhes: Investi até que eu venha;"},"fr":{"prompt":"Dans la parabole des mines, combien de serviteurs l’homme de haute naissance appela-t-il avant de partir ?","bible_ref":"Luc 19:13","verse_text":"Il appela dix de ses serviteurs, leur donna dix mines, et leur dit: Faites-les valoir jusqu’à ce que je revienne."},"en":{"prompt":"In the parable of the pounds, how many servants did the nobleman call before he left?","bible_ref":"Luke 19:13","verse_text":"And he called his ten servants, and delivered them ten pounds, and said unto them, Occupy till I come."},"es":{"prompt":"En la parábola de las minas, ¿cuántos siervos llamó el hombre noble antes de partir?","bible_ref":"Lucas 19:13","verse_text":"Mas llamados diez siervos suyos, les dió diez minas, y díjoles: Negociad entre tanto que vengo."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Dez"},"fr":{"text":"Dix"},"en":{"text":"Ten"},"es":{"text":"Diez"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Três"},"fr":{"text":"Trois"},"en":{"text":"Three"},"es":{"text":"Tres"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Cinco"},"fr":{"text":"Cinq"},"en":{"text":"Five"},"es":{"text":"Cinco"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Doze"},"fr":{"text":"Douze"},"en":{"text":"Twelve"},"es":{"text":"Doce"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-hard-015","type":"choice","level":"hard","testament":"nt","book":"JHN","chapter":2,"verse_start":20,"verse_end":20,"texts":{"pt":{"prompt":"Segundo os judeus em João 2:20, quantos anos se levou a edificar o templo?","bible_ref":"João 2:20","verse_text":"Os judeus, pois, disseram: Durante quarenta e seis anos este Templo foi edificado, e tu o levantarás tu em três dias?"},"fr":{"prompt":"Selon les Juifs en Jean 2:20, combien d’années a-t-il fallu pour bâtir le temple ?","bible_ref":"Jean 2:20","verse_text":"Les Juifs dirent: Il a fallu quarante-six ans pour bâtir ce temple, et toi, en trois jours tu le relèveras!"},"en":{"prompt":"According to the Jews in John 2:20, how many years was the temple in building?","bible_ref":"John 2:20","verse_text":"Then said the Jews, Forty and six years was this temple in building, and wilt thou rear it up in three days?"},"es":{"prompt":"Según los judíos en Juan 2:20, ¿en cuántos años fue edificado el templo?","bible_ref":"Juan 2:20","verse_text":"Dijeron luego los Judíos: En cuarenta y seis años fué este templo edificado, ¿y tú en tres días lo levantarás?"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Quarenta e seis"},"fr":{"text":"Quarante-six"},"en":{"text":"Forty and six"},"es":{"text":"Cuarenta y seis"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Doze"},"fr":{"text":"Douze"},"en":{"text":"Twelve"},"es":{"text":"Doce"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Quarenta"},"fr":{"text":"Quarante"},"en":{"text":"Forty"},"es":{"text":"Cuarenta"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Setenta"},"fr":{"text":"Septante"},"en":{"text":"Seventy"},"es":{"text":"Setenta"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-hard-016","type":"choice","level":"hard","testament":"nt","book":"JHN","chapter":5,"verse_start":2,"verse_end":2,"texts":{"pt":{"prompt":"Segundo João 5:2, quantas entradas cobertas tinha o tanque de Betesda?","bible_ref":"João 5:2","verse_text":"E há em Jerusalém à porta das ovelhas um tanque, que em hebraico se chama Betesda, que tem cinco entradas cobertas."},"fr":{"prompt":"Selon Jean 5:2, combien de portiques avait la piscine de Béthesda ?","bible_ref":"Jean 5:2","verse_text":"Or, à Jérusalem, près de la porte des brebis, il y a une piscine qui s’appelle en hébreu Béthesda, et qui a cinq portiques."},"en":{"prompt":"According to John 5:2, how many porches had the pool of Bethesda?","bible_ref":"John 5:2","verse_text":"Now there is at Jerusalem by the sheep market a pool, which is called in the Hebrew tongue Bethesda, having five porches."},"es":{"prompt":"Según Juan 5:2, ¿cuántos portales tenía el estanque de Bethesda?","bible_ref":"Juan 5:2","verse_text":"Y hay en Jerusalem á la puerta del ganado un estanque, que en hebraico es llamado Bethesda, el cual tiene cinco portales."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Cinco"},"fr":{"text":"Cinq"},"en":{"text":"Five"},"es":{"text":"Cinco"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Três"},"fr":{"text":"Trois"},"en":{"text":"Three"},"es":{"text":"Tres"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Sete"},"fr":{"text":"Sept"},"en":{"text":"Seven"},"es":{"text":"Siete"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Doze"},"fr":{"text":"Douze"},"en":{"text":"Twelve"},"es":{"text":"Doce"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-hard-017","type":"choice","level":"hard","testament":"nt","book":"JHN","chapter":19,"verse_start":39,"verse_end":39,"texts":{"pt":{"prompt":"Para o corpo de Jesus, quantos arráteis de mirra e aloés trouxe Nicodemos, aproximadamente?","bible_ref":"João 19:39","verse_text":"E veio também Nicodemos, (aquele que antes de noite tinha vindo a Jesus) trazendo um composto de mirra e aloés, de quase cem arráteis."},"fr":{"prompt":"Pour le corps de Jésus, environ combien de livres de myrrhe et d’aloès Nicodème apporta-t-il ?","bible_ref":"Jean 19:39","verse_text":"Nicodème, qui auparavant était allé de nuit vers Jésus, vint aussi, apportant un mélange d’environ cent livres de myrrhe et d’aloès."},"en":{"prompt":"For the body of Jesus, about how many pounds of myrrh and aloes did Nicodemus bring?","bible_ref":"John 19:39","verse_text":"And there came also Nicodemus, which at the first came to Jesus by night, and brought a mixture of myrrh and aloes, about an hundred pound weight."},"es":{"prompt":"Para el cuerpo de Jesús, ¿cuántas libras de mirra y de áloes trajo Nicodemo, poco más o menos?","bible_ref":"Juan 19:39","verse_text":"Y vino también Nicodemo, el que antes había venido á Jesús de noche, trayendo un compuesto de mirra y de áloes, como cien libras."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Cem"},"fr":{"text":"Cent"},"en":{"text":"An hundred"},"es":{"text":"Cien"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Dez"},"fr":{"text":"Dix"},"en":{"text":"Ten"},"es":{"text":"Diez"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Trinta"},"fr":{"text":"Trente"},"en":{"text":"Thirty"},"es":{"text":"Treinta"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Mil"},"fr":{"text":"Mille"},"en":{"text":"A thousand"},"es":{"text":"Mil"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-hard-018","type":"choice","level":"hard","testament":"nt","book":"JHN","chapter":11,"verse_start":16,"verse_end":16,"texts":{"pt":{"prompt":"Por que outro nome era chamado o discípulo Tomé?","bible_ref":"João 11:16","verse_text":"Disse pois Tomé, chamado o Dídimo, aos colegas discípulos: Vamos nós também, para que com ele morramos."},"fr":{"prompt":"De quel autre nom était appelé le disciple Thomas ?","bible_ref":"Jean 11:16","verse_text":"Sur quoi Thomas, appelé Didyme, dit aux autres disciples: Allons aussi, afin de mourir avec lui."},"en":{"prompt":"By what other name was the disciple Thomas called?","bible_ref":"John 11:16","verse_text":"Then said Thomas, which is called Didymus, unto his fellowdisciples, Let us also go, that we may die with him."},"es":{"prompt":"¿Con qué otro nombre se llamaba el discípulo Tomás?","bible_ref":"Juan 11:16","verse_text":"Dijo entonces Tomás, el que se dice el Dídimo, á sus condiscípulos: Vamos también nosotros, para que muramos con él."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Dídimo"},"fr":{"text":"Didyme"},"en":{"text":"Didymus"},"es":{"text":"Dídimo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Cefas"},"fr":{"text":"Céphas"},"en":{"text":"Cephas"},"es":{"text":"Cephas"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Tadeu"},"fr":{"text":"Thaddée"},"en":{"text":"Thaddaeus"},"es":{"text":"Tadeo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Boanerges"},"fr":{"text":"Boanergès"},"en":{"text":"Boanerges"},"es":{"text":"Boanerges"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-hard-019","type":"choice","level":"hard","testament":"nt","book":"JHN","chapter":12,"verse_start":4,"verse_end":5,"texts":{"pt":{"prompt":"Segundo Judas Iscariotes, por quanto se podia ter vendido o perfume de Maria?","bible_ref":"João 12:4-5","verse_text":"Então disse Judas de Simão Iscariotes, um de seus discípulos, o que o trairia: Por que se não vendeu este óleo perfumado por trezentos dinheiros, e se deu aos pobres?"},"fr":{"prompt":"Selon Judas Iscariot, pour combien aurait-on pu vendre le parfum de Marie ?","bible_ref":"Jean 12:4-5","verse_text":"Un de ses disciples, Judas Iscariot, fils de Simon, celui qui devait le livrer, dit: Pourquoi n’a-t-on pas vendu ce parfum trois cents deniers, pour les donner aux pauvres?"},"en":{"prompt":"According to Judas Iscariot, for how much could Mary’s ointment have been sold?","bible_ref":"John 12:4-5","verse_text":"Then saith one of his disciples, Judas Iscariot, Simon’s son, which should betray him, Why was not this ointment sold for three hundred pence, and given to the poor?"},"es":{"prompt":"Según Judas Iscariote, ¿por cuánto se podía haber vendido el ungüento de María?","bible_ref":"Juan 12:4-5","verse_text":"Y dijo uno de sus discípulos, Judas Iscariote, hijo de Simón, el que le había de entregar: ¿Por qué no se ha vendido este ungüento por trescientos dineros, y se dió á los pobres?"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Trezentos dinheiros"},"fr":{"text":"Trois cents deniers"},"en":{"text":"Three hundred pence"},"es":{"text":"Trescientos dineros"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Trinta dinheiros"},"fr":{"text":"Trente deniers"},"en":{"text":"Thirty pence"},"es":{"text":"Treinta dineros"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Cem dinheiros"},"fr":{"text":"Cent deniers"},"en":{"text":"An hundred pence"},"es":{"text":"Cien dineros"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Mil dinheiros"},"fr":{"text":"Mille deniers"},"en":{"text":"A thousand pence"},"es":{"text":"Mil dineros"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-hard-020","type":"choice","level":"hard","testament":"nt","book":"ACT","chapter":4,"verse_start":36,"verse_end":36,"texts":{"pt":{"prompt":"Barnabé, o levita a quem os apóstolos deram esse sobrenome, era natural de que terra?","bible_ref":"Atos 4:36","verse_text":"E José, chamado pelos apóstolos pelo sobrenome de Barnabé (que traduzido é filho da consolação), levita, natural do Chipre,"},"fr":{"prompt":"Barnabas, le Lévite ainsi surnommé par les apôtres, était originaire de quel pays ?","bible_ref":"Actes 4:36","verse_text":"Joseph, surnommé par les apôtres Barnabas, ce qui signifie fils d’exhortation, Lévite, originaire de Chypre,"},"en":{"prompt":"Barnabas, the Levite so surnamed by the apostles, was of what country?","bible_ref":"Acts 4:36","verse_text":"And Joses, who by the apostles was surnamed Barnabas, (which is, being interpreted, The son of consolation,) a Levite, and of the country of Cyprus,"},"es":{"prompt":"Bernabé, el levita así llamado por los apóstoles, ¿de qué tierra era natural?","bible_ref":"Hechos 4:36","verse_text":"Entonces José, que fué llamado de los apóstoles por sobrenombre, Bernabé, (que es interpretado, Hijo de consolación) Levita, natural de Cipro,"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Chipre"},"fr":{"text":"Chypre"},"en":{"text":"Cyprus"},"es":{"text":"Cipro"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Creta"},"fr":{"text":"Crète"},"en":{"text":"Crete"},"es":{"text":"Creta"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Cilícia"},"fr":{"text":"Cilicie"},"en":{"text":"Cilicia"},"es":{"text":"Cilicia"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Egito"},"fr":{"text":"Égypte"},"en":{"text":"Egypt"},"es":{"text":"Egipto"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-hard-021","type":"choice","level":"hard","testament":"nt","book":"ACT","chapter":14,"verse_start":12,"verse_end":12,"texts":{"pt":{"prompt":"Em Listra, a quem chamava o povo Júpiter?","bible_ref":"Atos 14:12","verse_text":"E chamaram a Barnabé de Júpiter; e a Paulo, de Mercúrio; porque este era o líder ao falar."},"fr":{"prompt":"À Lystre, qui la foule appelait-elle Jupiter ?","bible_ref":"Actes 14:12","verse_text":"Ils appelaient Barnabas Jupiter, et Paul Mercure, parce que c’était lui qui portait la parole."},"en":{"prompt":"At Lystra, whom did the people call Jupiter?","bible_ref":"Acts 14:12","verse_text":"And they called Barnabas, Jupiter; and Paul, Mercurius, because he was the chief speaker."},"es":{"prompt":"En Listra, ¿a quién llamaba la gente Júpiter?","bible_ref":"Hechos 14:12","verse_text":"Y á Bernabé llamaban Júpiter, y á Pablo, Mercurio, porque era el que llevaba la palabra."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Barnabé"},"fr":{"text":"Barnabas"},"en":{"text":"Barnabas"},"es":{"text":"Bernabé"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Paulo"},"fr":{"text":"Paul"},"en":{"text":"Paul"},"es":{"text":"Pablo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Silas"},"fr":{"text":"Silas"},"en":{"text":"Silas"},"es":{"text":"Silas"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Timóteo"},"fr":{"text":"Timothée"},"en":{"text":"Timotheus"},"es":{"text":"Timoteo"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan2-hard-022","type":"order","level":"hard","testament":"nt","book":"MAT","chapter":22,"verse_start":21,"verse_end":21,"texts":{"pt":{"prompt":"Ordena estes episódios de Mateus pela ordem em que aconteceram.","bible_ref":"Mateus 22:21","verse_text":null},"fr":{"prompt":"Mets ces épisodes de Matthieu dans l’ordre où ils se sont produits.","bible_ref":"Matthieu 22:21","verse_text":null},"en":{"prompt":"Put these episodes from Matthew in the order they happened.","bible_ref":"Matthew 22:21","verse_text":null},"es":{"prompt":"Ordena estos episodios de Mateo según ocurrieron.","bible_ref":"Mateo 22:21","verse_text":null}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"Jesus diz: «Dai a César o que é de César»","ref":"Mateus 22:21"},"fr":{"text":"Jésus dit : « Rendez à César ce qui est à César »","ref":"Matthieu 22:21"},"en":{"text":"Jesus says, “Render unto Cæsar the things which are Cæsar’s”","ref":"Matthew 22:21"},"es":{"text":"Jesús dice: «Pagad a César lo que es de César»","ref":"Mateo 22:21"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Os saduceus falam de sete irmãos e uma só mulher","ref":"Mateus 22:25"},"fr":{"text":"Les sadducéens parlent de sept frères et d’une seule femme","ref":"Matthieu 22:25"},"en":{"text":"The Sadducees tell of seven brethren and one wife","ref":"Matthew 22:25"},"es":{"text":"Los saduceos hablan de siete hermanos y una mujer","ref":"Mateo 22:25"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Jesus pergunta: «De quem é filho o Cristo?»","ref":"Mateus 22:42"},"fr":{"text":"Jésus demande : « De qui le Christ est-il fils ? »","ref":"Matthieu 22:42"},"en":{"text":"Jesus asks, “Whose son is Christ?”","ref":"Matthew 22:42"},"es":{"text":"Jesús pregunta: «¿De quién es Hijo el Cristo?»","ref":"Mateo 22:42"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Jesus diz que do templo não ficará pedra sobre pedra","ref":"Mateus 24:1-2"},"fr":{"text":"